    width: 2rem;
    height: 2rem;
    border-radius: 12px;
    flex-shrink: 0;
    font-size: 0.875rem;
    font-weight: 800;
    color: var(--lux-primary);
    background: rgba(var(--lux-primary-rgb), 0.08);
    border: 1px solid rgba(var(--lux-primary-rgb), 0.12);
}

.lux-settings-option__copy {
