    align-items: flex-start;
    gap: 0.45rem;
    min-width: 0;
}

.lux-settings-toggle__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.625rem;
    height: 1.625rem;
    border-radius: 8px;
    flex-shrink: 0;
    color: var(--lux-primary);
    background: rgba(var(--lux-primary-rgb), 0.08);
    border: 1px solid rgba(var(--lux-primary-rgb), 0.12);
    font-size: 0.75rem;
}

.lux-settings-toggle__copy strong {
    display: block;
    font-size: 0.75rem;
    font-weight: 800;
    color: var(--lux-text);
    line-height: 1.2;
}

.lux-settings-toggle__copy span {
    display: block;
    margin-top: 0.08rem;
    font-size: 0.6875rem;
    line-height: 1.35;
    color: var(--lux-muted);
}

.lux-settings-toggle__switch {
    margin: 0;
