/* ========== luxury-assist-dock.css ========== */

/* ========== Assist dock — draggable FAB + icon stack ========== */

.lux-assist-dock {
    position: fixed;
    right: 0;
    z-index: 1040;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.55rem;
    pointer-events: auto;
    touch-action: none;
}

.lux-assist-dock.is-dragging {
    user-select: none;
}

.lux-assist-dock__backdrop {
    position: fixed;
    inset: 0;
    z-index: 1039;
    border: none;
    padding: 0;
    margin: 0;
    background: transparent;
    cursor: default;
    pointer-events: auto;
}

.lux-assist-dock__icons {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.55rem;
    padding-right: 6px;
    pointer-events: auto;
    max-height: 0;
    opacity: 0;
    overflow: hidden;
    transform: translateY(6px);
    transition:
        max-height 0.28s ease,
        opacity 0.22s ease,
        transform 0.22s ease;
}

.lux-assist-dock__icons.is-visible {
    max-height: 320px;
    opacity: 1;
    transform: translateY(0);
}

@keyframes luxAssistIconsIn {
    from {
        opacity: 0;
        transform: translateY(8px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.lux-assist-dock__icon-btn {
    width: 44px;
    height: 44px;
    padding: 0;
    border: none;
    border-radius: 50%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    color: #fff;
    box-shadow: 0 6px 20px rgba(15, 23, 42, 0.18);
    transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease;
}

.lux-assist-dock__icon-btn:hover {
    transform: translateY(-2px) scale(1.05);
    box-shadow: 0 12px 28px rgba(15, 23, 42, 0.22);
    filter: brightness(1.06);
}

.lux-assist-dock__icon-btn:focus-visible {
    outline: 2px solid #6366f1;
    outline-offset: 2px;
}

.lux-assist-dock__icon-btn--ai {
    border: 2px solid rgba(255, 255, 255, 0.92);
    background: linear-gradient(145deg, #6d5dfc, #10b981);
}

.lux-assist-dock__icon-btn--help {
    border: 2px solid rgba(255, 255, 255, 0.92);
    background: linear-gradient(145deg, #5ea657, #059669);
    font-size: 1.1rem;
}

.lux-assist-dock__icon-btn--mobile {
    width: auto;
    height: auto;
    background: transparent;
    box-shadow: none;
    border-radius: 0;
}

.lux-assist-dock__mobile-shell {
    pointer-events: none;
}

.lux-assist-dock__icon-btn--mobile:hover {
    transform: none;
    filter: none;
}

.lux-assist-dock__trigger {
    position: relative;
    pointer-events: auto;
    width: 52px;
    min-height: 92px;
    height: auto;
    padding: 0.65rem 0.35rem;
    border: none;
    border-radius: 16px 0 0 16px;
    cursor: grab;
    color: #fff;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(165deg, #6d5dfc 0%, #4338ca 42%, #059669 100%);
    box-shadow:
        -6px 0 28px rgba(91, 95, 244, 0.28),
        0 0 0 1px rgba(255, 255, 255, 0.12) inset;
    transition: box-shadow 0.2s ease, filter 0.2s ease;
    overflow: hidden;
    touch-action: none;
}

.lux-assist-dock__trigger-inner {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 0.35rem;
}

.lux-assist-dock__trigger-text {
    writing-mode: vertical-rl;
    text-orientation: mixed;
    transform: rotate(180deg);
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    opacity: 0.95;
    line-height: 1;
}

.lux-assist-dock__trigger-glow {
    position: absolute;
    inset: 0;
    background: radial-gradient(circle at 80% 20%, rgba(255, 255, 255, 0.35), transparent 55%);
    pointer-events: none;
}

.lux-assist-dock.is-dragging .lux-assist-dock__trigger {
    cursor: grabbing;
    box-shadow:
        -12px 0 36px rgba(91, 95, 244, 0.38),
        0 0 0 1px rgba(255, 255, 255, 0.16) inset;
    filter: brightness(1.04);
}

.lux-assist-dock__trigger-sparkle {
    position: relative;
    filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.12));
}

.lux-assist-dock__trigger-icon {
    position: relative;
    font-size: 1.05rem;
    line-height: 1;
}

.lux-assist-dock__trigger:hover {
    filter: brightness(1.06);
    box-shadow:
        -12px 0 36px rgba(91, 95, 244, 0.34),
        0 0 0 1px rgba(255, 255, 255, 0.16) inset;
}

.lux-assist-dock__trigger:focus-visible {
    outline: 2px solid #6366f1;
    outline-offset: 2px;
}

.lux-assist-dock.is-open .lux-assist-dock__trigger {
    background: linear-gradient(165deg, #475569 0%, #334155 100%);
    box-shadow: -4px 0 20px rgba(15, 23, 42, 0.2);
}

@media (max-width: 640px) {
    .lux-assist-dock__trigger {
        width: 48px;
        min-height: 84px;
    }

    .lux-assist-dock__icon-btn--ai {
        width: 40px;
        height: 40px;
    }

    .lux-assist-dock__icon-btn--help {
        width: 40px;
        height: 40px;
        font-size: 1rem;
    }
}

@media print {
    .lux-assist-dock,
    .lux-assist-dock__backdrop {
        display: none !important;
    }
}

@media (prefers-reduced-motion: reduce) {
    .lux-assist-dock__icons {
        transition: none;
    }

    .lux-assist-dock__icon-btn,
    .lux-assist-dock__trigger {
        transition: none;
    }
}

