}

.lux-user-panel__task-project {
    margin: 0;
    font-size: 0.6875rem;
    color: #64748b;
    line-height: 1.35;
}

.lux-user-panel__task-empty,
.lux-user-panel__empty {
    margin: 0;
    font-size: 0.8125rem;
    color: #64748b;
    text-align: center;
    padding: 0.75rem 0.625rem;
}

.lux-user-panel__links {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.625rem;
}

.lux-user-panel__link-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 36px;
    padding: 0.4rem 0.65rem;
    border-radius: 9911px;
    font-size: 0.75rem;
    font-weight: 700;
    text-decoration: none;
    color: #fff;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
