    line-height: 1.2;
}

.lux-today-panel__date {
    margin: 0;
    font-size: 0.8125rem;
    color: #64748b;
}

.lux-today-panel__close {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 34px;
    height: 34px;
    padding: 0;
    border: none;
    border-radius: 9911px;
    background: #f1f5f9;
    color: #64748b;
