    margin-bottom: 0.75rem;
}

.lux-today-panel__ring {
    --lux-progress: 0;
    flex-shrink: 0;
    width: 88px;
    height: 88px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    background: conic-gradient(
        var(--lux-primary, #5b5ff4) calc(var(--lux-progress) * 1%),
