.lux-today-panel__timeline {
    list-style: none;
    margin: 0;
    padding: 0;
    position: relative;
}

.lux-today-panel__timeline::before {
    content: "";
    position: absolute;
    left: 12px;
    top: 8px;
    bottom: 8px;
    width: 2px;
    background: linear-gradient(
        180deg,
        rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35),
