    white-space: nowrap;
}

.lux-activity-group__name {
    font-size: 0.6875rem;
    font-weight: 800;
    color: #0f172a;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-activity-group__meta {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    flex-shrink: 0;
