    border-color: rgba(245, 158, 11, 0.35);
    background: rgba(245, 158, 11, 0.1);
}

.lux-activity-list .lux-project-row__action.is-checklist.is-done,
.lux-activity-pending .lux-project-row__action.is-checklist.is-done {
