    color: #be123c;
}

.lux-activity-pending__head .lux-project-row__action,
.lux-activity-holidays__head .lux-project-row__actions {
    flex-shrink: 0;
}

.lux-activity-item__detail {
    margin-top: 0.35rem;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.96);
