    --lux-search-radius-sm: 14px;
    width: 100%;
    max-width: none;
    padding: 0 16px 28px;
    box-sizing: border-box;
}

/* —— Hero —— */
.lux-search-hero {
    position: relative;
    margin: 8px 0 16px;
    padding: 24px 28px;
    border-radius: var(--lux-search-radius);
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.92));
    box-shadow: 0 24px 60px rgba(15, 23, 42, 0.07);
    overflow: hidden;
}

.lux-search-hero--compact {
    padding: 20px 24px;
}

.lux-search-hero__glow {
    position: absolute;
    top: -45%;
    right: -5%;
    width: 360px;
    height: 360px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18), transparent 70%);
    pointer-events: none;
}

.lux-search-hero__glow--left {
    top: auto;
    right: auto;
    bottom: -55%;
    left: -6%;
    width: 280px;
    height: 280px;
    background: radial-gradient(circle, rgba(20, 184, 166, 0.12), transparent 70%);
}

.lux-search-hero__inner {
    position: relative;
    z-index: 1;
}

.lux-search-hero__inner--split {
    display: grid;
    grid-template-columns: minmax(220px, 340px) minmax(0, 1fr);
    gap: 1.5rem;
    align-items: center;
}

.lux-search-hero__copy {
    min-width: 0;
}

.lux-search-hero__kicker {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    margin: 0 0 0.4rem;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-search-hero__kicker i {
    color: var(--lux-primary, #5b5ff4);
}

.lux-search-hero__title {
    margin: 0 0 0.3rem;
    font-size: clamp(1.35rem, 2.2vw, 1.75rem);
    font-weight: 800;
    letter-spacing: -0.04em;
    line-height: 1.15;
    color: #0f172a;
}

.lux-search-hero__subtitle {
    margin: 0;
    font-size: 0.875rem;
    line-height: 1.45;
    color: #64748b;
}

/* —— Search bar —— */
.lux-search-bar {
    display: flex;
    align-items: stretch;
    gap: 0.625rem;
    padding: 0.4rem;
    border-radius: 9911px;
    background: #fff;
    border: 1px solid rgba(148, 163, 184, 0.35);
    box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.8) inset,
        0 12px 32px rgba(15, 23, 42, 0.08);
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
    width: 100%;
}

.lux-search-bar:focus-within {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.45);
    box-shadow:
        0 0 0 3px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12),
        0 12px 32px rgba(15, 23, 42, 0.08);
}

.lux-search-bar__icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    flex-shrink: 0;
    color: #94a3b8;
    font-size: 1.125rem;
}

.lux-search-bar__input {
    flex: 1;
    min-width: 0;
    border: none;
    background: transparent;
    font-size: 1rem;
    font-weight: 500;
    color: #0f172a;
    padding: 0.65rem 0;
    outline: none;
}

.lux-search-bar__input::placeholder {
    color: #94a3b8;
    font-weight: 400;
}

.lux-search-bar__clear {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    margin: auto 0;
    padding: 0;
    border: none;
    border-radius: 9911px;
    background: #f1f5f9;
    color: #64748b;
    cursor: pointer;
    flex-shrink: 0;
    transition: background 0.15s ease, color 0.15s ease;
}

.lux-search-bar__clear:hover {
    background: #e2e8f0;
    color: #0f172a;
}

.lux-search-bar__submit {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    min-width: 108px;
    padding: 0 1.25rem;
    border: none;
    border-radius: 9911px;
    font-size: 0.875rem;
    font-weight: 700;
    color: #fff;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
    box-shadow: 0 8px 20px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.32);
    cursor: pointer;
    flex-shrink: 0;
    transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.lux-search-bar__submit:hover:not(:disabled) {
    transform: translateY(-1px);
    box-shadow: 0 12px 24px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.38);
}

.lux-search-bar__submit:disabled {
    opacity: 0.55;
    cursor: not-allowed;
}

.lux-search-bar__submit.is-loading {
    pointer-events: none;
}

/* —— Layout: sidebar + results panel —— */
.lux-search-layout {
    display: grid;
    grid-template-columns: 260px minmax(0, 1fr);
    gap: 16px;
    align-items: start;
    min-height: calc(100vh - 220px);
}

.lux-search-sidebar {
    display: flex;
    flex-direction: column;
    gap: 12px;
    position: sticky;
    top: 72px;
}

.lux-search-sidebar__card {
    padding: 1rem;
    border-radius: var(--lux-search-radius-sm);
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: #fff;
    box-shadow: 0 8px 24px rgba(15, 23, 42, 0.04);
}

.lux-search-sidebar__title {
    margin: 0 0 0.75rem;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: #64748b;
}

/* —— Filters —— */
.lux-search-filters--stack {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.lux-search-filter {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.45rem 0.875rem;
    border-radius: 12px;
    border: 1px solid #e2e8f0;
    background: #fff;
    font-size: 0.8125rem;
    font-weight: 700;
    color: #475569;
    cursor: pointer;
    transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}

.lux-search-filter--stack {
    width: 100%;
    justify-content: space-between;
    text-align: left;
}

.lux-search-filter__leading {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
}

.lux-search-filter__leading i {
    font-size: 0.9375rem;
    opacity: 0.85;
}

.lux-search-filter:hover:not(:disabled) {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.25);
    color: var(--lux-primary, #5b5ff4);
}

.lux-search-filter:disabled {
    opacity: 0.45;
    cursor: not-allowed;
}

.lux-search-filter.is-active {
    color: #fff;
    border-color: transparent;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
    box-shadow: 0 6px 16px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}

.lux-search-filter__count {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 1.35rem;
    height: 1.35rem;
    padding: 0 0.35rem;
    border-radius: 9911px;
    font-size: 0.6875rem;
    font-weight: 800;
    background: rgba(15, 23, 42, 0.08);
}

.lux-search-filter.is-active .lux-search-filter__count {
    background: rgba(255, 255, 255, 0.22);
}

/* —— Sidebar insights —— */
.lux-search-insights {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.625rem;
}

.lux-search-insights li {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 0.625rem 0.75rem;
    border-radius: 12px;
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    font-size: 0.75rem;
    color: #64748b;
}

.lux-search-insights strong {
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-search-sidebar-tips {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.lux-search-sidebar-tips li {
    display: flex;
    gap: 0.75rem;
    align-items: flex-start;
}

.lux-search-sidebar-tips i {
    flex-shrink: 0;
    width: 28px;
    height: 28px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--lux-primary, #5b5ff4);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    font-size: 0.875rem;
}

.lux-search-sidebar-tips strong {
    display: block;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
    margin-bottom: 0.1rem;
}

.lux-search-sidebar-tips span {
    font-size: 0.75rem;
    color: #64748b;
    line-height: 1.4;
}

/* —— Results panel —— */
.lux-search-panel {
    border-radius: var(--lux-search-radius);
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: #fff;
    box-shadow: 0 16px 40px rgba(15, 23, 42, 0.06);
    overflow: hidden;
    min-height: 480px;
    display: flex;
    flex-direction: column;
}

.lux-search-panel__header {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 1.125rem 1.25rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
    background: linear-gradient(
        135deg,
        rgba(var(--lux-primary-rgb, 91, 95, 244), 0.04) 0%,
        rgba(20, 184, 166, 0.03) 100%
    );
}

.lux-search-panel__kicker {
    margin: 0 0 0.2rem;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-search-panel__title {
    margin: 0;
    font-size: 1.0625rem;
    font-weight: 700;
    color: #334155;
    line-height: 1.35;
}

.lux-search-panel__title strong {
    color: #0f172a;
    font-weight: 800;
}

.lux-search-panel__badge {
    font-size: 0.6875rem;
    font-weight: 700;
    padding: 0.4rem 0.75rem;
    border-radius: 9911px;
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    border: 1px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16);
    white-space: nowrap;
}

.lux-search-panel__body {
    flex: 1;
    padding: 1rem 1.25rem 1.25rem;
    display: flex;
    flex-direction: column;
}

/* —— Results list —— */
.lux-search-results {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    flex: 1;
}

.lux-search-result {
    display: grid;
    grid-template-columns: auto auto minmax(0, 1fr) auto;
    gap: 0.875rem;
    align-items: start;
    padding: 1.125rem 1.25rem;
    border-radius: var(--lux-search-radius-sm);
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: linear-gradient(180deg, #fff 0%, #fafbfc 100%);
    box-shadow: 0 6px 18px rgba(15, 23, 42, 0.04);
    transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}

.lux-search-result:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.24);
    box-shadow: 0 14px 32px rgba(15, 23, 42, 0.08);
    transform: translateY(-1px);
}

.lux-search-result__rank-col {
    padding-top: 0.15rem;
}

.lux-search-result__rank {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 2rem;
    height: 2rem;
    padding: 0 0.35rem;
    border-radius: 12px;
    font-size: 0.75rem;
    font-weight: 800;
    color: #64748b;
    background: #f1f5f9;
    border: 1px solid #e2e8f0;
}

.lux-search-result__rank.is-top {
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.2);
}

.lux-search-result__icon {
    flex-shrink: 0;
    width: 44px;
    height: 44px;
    border-radius: 13px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.125rem;
}

.lux-search-result__icon--project {
    color: var(--lux-primary, #5b5ff4);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-search-result__icon--task {
    color: #0d9488;
    background: rgba(20, 184, 166, 0.12);
}

.lux-search-result__body {
    min-width: 0;
}

.lux-search-result__head {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.45rem;
    margin-bottom: 0.35rem;
}

.lux-search-result__type {
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding: 0.2rem 0.625rem;
    border-radius: 9911px;
}

.lux-search-result__type--project {
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-search-result__type--task {
    color: #0f766e;
    background: rgba(20, 184, 166, 0.12);
}

.lux-search-result__path {
    font-size: 0.6875rem;
    font-weight: 600;
    color: #94a3b8;
    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

.lux-search-result__relevance-label {
    margin-left: auto;
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
    padding: 0.15rem 0.45rem;
    border-radius: 9911px;
    background: #f8fafc;
    border: 1px solid #e2e8f0;
}

.lux-search-result__title {
    display: block;
    margin: 0 0 0.35rem;
    font-size: 1.0625rem;
    font-weight: 800;
    letter-spacing: -0.02em;
    line-height: 1.35;
    color: #0f172a;
    text-decoration: none;
    transition: color 0.15s ease;
}

.lux-search-result__title:hover {
    color: var(--lux-primary, #5b5ff4);
    text-decoration: none;
}

.lux-search-result__title del {
    color: #94a3b8;
}

.lux-search-result__summary {
    margin: 0 0 0.65rem;
    font-size: 0.8125rem;
    line-height: 1.55;
    color: #64748b;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.lux-search-result__summary mark,
.lux-search-result__title mark {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16);
    color: var(--lux-primary-dark, #3730a3);
    padding: 0 0.15rem;
    border-radius: 3px;
}

.lux-search-result__badge {
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    padding: 0.2rem 0.45rem;
    border-radius: 9911px;
    color: #b91c1c;
    background: #fee2e2;
}

.lux-search-result__footer {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
}

.lux-search-result__reasons {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem;
}

.lux-search-result__reason {
    font-size: 0.75rem;
    font-weight: 700;
    padding: 0.2rem 0.625rem;
    border-radius: 9911px;
    color: #475569;
    background: #f1f5f9;
    border: 1px solid #e2e8f0;
}

.lux-search-result__meter {
    display: flex;
    align-items: center;
    gap: 0.625rem;
    min-width: 120px;
}

.lux-search-result__meter-track {
    flex: 1;
    height: 6px;
    border-radius: 9911px;
    background: #e2e8f0;
    overflow: hidden;
    min-width: 72px;
}

.lux-search-result__meter-fill {
    height: 100%;
    border-radius: inherit;
    background: linear-gradient(90deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
    transition: width 0.35s ease;
}

.lux-search-result__meter-value {
    font-size: 0.6875rem;
    font-weight: 800;
    color: #64748b;
    white-space: nowrap;
}

.lux-search-result__open {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 38px;
    height: 38px;
    margin-top: 0.15rem;
    border-radius: 12px;
    color: #64748b;
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    text-decoration: none;
    transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease, transform 0.15s ease;
}

.lux-search-result__open:hover {
    color: #fff;
    background: var(--lux-primary, #5b5ff4);
    border-color: transparent;
    transform: translateY(-1px);
    text-decoration: none;
}

/* —— Pagination —— */
.lux-search-pagination {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 0.875rem;
    margin-top: 1.25rem;
    padding-top: 1rem;
    border-top: 1px solid #e2e8f0;
}

.lux-search-pagination__summary {
    font-size: 0.8125rem;
    color: #64748b;
}

.lux-search-pagination__summary strong {
    color: #0f172a;
    font-weight: 800;
}

.lux-search-pagination__controls {
    display: flex;
    align-items: center;
    gap: 0.35rem;
}

.lux-search-pagination__btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    padding: 0;
    border: 1px solid #e2e8f0;
    border-radius: 12px;
    background: #fff;
    color: #475569;
    cursor: pointer;
    transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.lux-search-pagination__btn:hover:not(:disabled) {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.3);
    color: var(--lux-primary, #5b5ff4);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

.lux-search-pagination__btn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.lux-search-pagination__pages {
    display: flex;
    align-items: center;
    gap: 0.25rem;
}

.lux-search-pagination__page {
    min-width: 36px;
    height: 36px;
    padding: 0 0.625rem;
    border: 1px solid transparent;
    border-radius: 12px;
    background: transparent;
    font-size: 0.8125rem;
    font-weight: 700;
    color: #64748b;
    cursor: pointer;
    transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.lux-search-pagination__page:hover {
    background: #f1f5f9;
    color: #0f172a;
}

.lux-search-pagination__page.is-active {
    color: #fff;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
    border-color: transparent;
    box-shadow: 0 4px 12px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}

.lux-search-pagination__ellipsis {
    padding: 0 0.25rem;
    color: #94a3b8;
    font-size: 0.875rem;
    user-select: none;
}

.lux-search-pagination__size {
    display: flex;
    align-items: center;
    gap: 0.625rem;
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
}

.lux-search-pagination__size select {
    height: 36px;
    padding: 0 0.65rem;
    border-radius: 12px;
    border: 1px solid #e2e8f0;
    background: #fff;
    font-size: 0.8125rem;
    font-weight: 700;
    color: #0f172a;
    cursor: pointer;
}

/* —— Landing / empty —— */
.lux-search-landing {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 2.5rem 1.5rem;
    border-radius: var(--lux-search-radius-sm);
    border: 1px dashed rgba(148, 163, 184, 0.4);
    background: rgba(248, 250, 252, 0.6);
    text-align: center;
    min-height: 320px;
}

.lux-search-landing__icon {
    width: 56px;
    height: 56px;
    margin: 0 auto 0.875rem;
    border-radius: 16px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.5rem;
    color: var(--lux-primary, #5b5ff4);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-search-landing__title {
    margin: 0 0 0.35rem;
    font-size: 1.0625rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-search-landing__text {
    margin: 0;
    font-size: 0.875rem;
    color: #64748b;
    line-height: 1.5;
    max-width: 32rem;
}

.lux-search-empty {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 2.5rem 1.5rem;
    text-align: center;
    min-height: 320px;
}

.lux-search-empty__icon {
    width: 64px;
    height: 64px;
    margin: 0 auto 1rem;
    border-radius: 18px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.75rem;
    color: #94a3b8;
    background: #f1f5f9;
}

.lux-search-empty__title {
    margin: 0 0 0.35rem;
    font-size: 1.125rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-search-empty__text {
    margin: 0;
    font-size: 0.875rem;
    color: #64748b;
    line-height: 1.5;
    max-width: 28rem;
}

/* —— Skeleton —— */
.lux-search-skeleton {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.lux-search-skeleton__row {
    display: grid;
    grid-template-columns: auto auto minmax(0, 1fr);
    gap: 0.875rem;
    padding: 1.125rem 1.25rem;
    border-radius: var(--lux-search-radius-sm);
    border: 1px solid #e2e8f0;
    background: #fff;
}

.lux-search-skeleton__icon {
    width: 44px;
    height: 44px;
    border-radius: 13px;
}

.lux-search-skeleton__lines {
    display: flex;
    flex-direction: column;
    gap: 0.625rem;
}

@media (max-width: 1100px) {
    .lux-search-hero__inner--split {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 900px) {
    .lux-search-layout {
        grid-template-columns: 1fr;
        min-height: auto;
    }

    .lux-search-sidebar {
        position: static;
    }

    .lux-search-filters--stack {
        flex-direction: row;
        flex-wrap: wrap;
    }

    .lux-search-filter--stack {
        width: auto;
        flex: 1;
        min-width: 140px;
    }
}

@media (max-width: 767px) {
    .lux-search-page {
        padding: 0 12px 20px;
    }

    .lux-search-hero,
    .lux-search-hero--compact {
        padding: 16px;
        border-radius: 16px;
    }

    .lux-search-bar {
        flex-wrap: wrap;
        border-radius: 16px;
        padding: 0.625rem;
    }

    .lux-search-bar__input {
        width: 100%;
        padding-left: 0.25rem;
    }

    .lux-search-bar__submit {
        width: 100%;
        min-height: 44px;
        border-radius: 12px;
    }

    .lux-search-result {
        grid-template-columns: auto minmax(0, 1fr);
        grid-template-rows: auto auto;
    }

    .lux-search-result__rank-col {
        grid-column: 1;
        grid-row: 1;
    }

    .lux-search-result__icon {
        grid-column: 2;
        grid-row: 1;
        justify-self: end;
    }

    .lux-search-result__body {
        grid-column: 1 / -1;
        grid-row: 2;
    }

    .lux-search-result__open {
        display: none;
    }

    .lux-search-pagination {
        flex-direction: column;
        align-items: stretch;
    }

    .lux-search-pagination__controls {
        justify-content: center;
    }

    .lux-search-pagination__size {
        justify-content: center;
    }
}

