}

.lux-appconfig-hero__meta-input:focus,
.lux-appconfig-hero__meta-select:focus {
    outline: none;
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.4);
    box-shadow: 0 0 0 2px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-appconfig-hero__meta-editor-actions {
    display: inline-flex;
    align-items: center;
    gap: 0.2rem;
    flex-shrink: 0;
}

.lux-appconfig-hero__meta-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    padding: 0;
    border: none;
    border-radius: 6px;
    background: #f1f5f9;
    color: #64748b;
    cursor: pointer;
}

.lux-appconfig-hero__meta-action--save:not(:disabled) {
    color: #fff;
    background: var(--lux-primary, #5b5ff4);
}

.lux-appconfig-hero__meta-action:disabled {
    opacity: 0.45;
    cursor: not-allowed;
}

.lux-appconfig-hero__meta-item dt,
.lux-appconfig-hero__meta-label {
    display: block;
    margin: 0;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #94a3b8;
    line-height: 1.2;
}

.lux-appconfig-hero__meta-item dd,
.lux-appconfig-hero__meta-value {
    display: block;
    margin: 0;
    font-size: 0.75rem;
    font-weight: 700;
    color: #0f172a;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    line-height: 1.25;
}

.lux-appconfig-hero__meta-item--popover {
    position: relative;
}

.lux-appconfig-hero__meta-trigger {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: 0.4rem;
    width: 100%;
    min-height: 44px;
    padding: 0.35rem 0.45rem;
    border: 1px dashed rgba(148, 163, 184, 0.55);
    border-radius: 8px;
    background: #fff;
    cursor: pointer;
    text-align: left;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
    transition:
        background 0.12s ease,
        border-color 0.12s ease,
        border-style 0.12s ease,
        box-shadow 0.12s ease,
        transform 0.12s ease;
}

.lux-appconfig-hero__meta-trigger:hover {
    border-style: solid;
    border-color: rgba(100, 116, 139, 0.45);
    box-shadow: 0 3px 12px rgba(15, 23, 42, 0.08);
    transform: translateY(-1px);
}

.lux-appconfig-hero__meta-trigger.is-open {
    border-style: solid;
    box-shadow: 0 4px 14px rgba(15, 23, 42, 0.1);
    transform: translateY(-1px);
}

.lux-appconfig-hero__meta-trigger--overridden {
    border-color: rgba(14, 116, 144, 0.35);
    background: rgba(14, 116, 144, 0.04);
}

.lux-appconfig-hero__meta-trigger--overridden:hover,
.lux-appconfig-hero__meta-trigger--overridden.is-open {
    border-color: rgba(14, 116, 144, 0.55);
    background: rgba(14, 116, 144, 0.08);
}

.lux-appconfig-hero__meta-trigger--locked {
    border-color: rgba(245, 158, 11, 0.35);
    background: rgba(245, 158, 11, 0.05);
}

.lux-appconfig-hero__meta-trigger--locked:hover,
.lux-appconfig-hero__meta-trigger--locked.is-open {
    border-color: rgba(245, 158, 11, 0.55);
    background: rgba(245, 158, 11, 0.1);
}

.lux-appconfig-hero__meta-trigger-icon {
    flex-shrink: 0;
    width: 24px;
    height: 24px;
    border-radius: 7px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
}

.lux-appconfig-hero__meta-trigger--overridden .lux-appconfig-hero__meta-trigger-icon {
    color: #0e7490;
    background: rgba(14, 116, 144, 0.12);
}

.lux-appconfig-hero__meta-trigger--locked .lux-appconfig-hero__meta-trigger-icon {
    color: #b45309;
    background: rgba(245, 158, 11, 0.14);
}

.lux-appconfig-hero__meta-trigger-text {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 0.1rem;
}

.lux-appconfig-hero__meta-trigger-label {
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #64748b;
    line-height: 1.2;
}

.lux-appconfig-hero__meta-trigger-value {
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.15;
}

.lux-appconfig-hero__meta-trigger--overridden.has-items .lux-appconfig-hero__meta-trigger-value {
    color: #0e7490;
}

.lux-appconfig-hero__meta-trigger--locked.has-items .lux-appconfig-hero__meta-trigger-value {
    color: #b45309;
}

.lux-appconfig-hero__meta-trigger-chevron {
    flex-shrink: 0;
    font-size: 0.6875rem;
    color: #94a3b8;
}

.lux-appconfig-hero__meta-trigger:hover .lux-appconfig-hero__meta-trigger-chevron,
.lux-appconfig-hero__meta-trigger.is-open .lux-appconfig-hero__meta-trigger-chevron {
    color: #64748b;
}

.lux-appconfig-hero__popover {
    max-height: 260px;
    display: flex;
    flex-direction: column;
    border-radius: 12px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: #fff;
    box-shadow: 0 18px 40px rgba(15, 23, 42, 0.18);
    overflow: hidden;
}

.lux-appconfig-hero__popover-head {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.55rem 0.65rem;
    border-bottom: 1px solid #e2e8f0;
    background: #f8fafc;
}

.lux-appconfig-hero__popover-head .fe {
    flex-shrink: 0;
    width: 24px;
    height: 24px;
    border-radius: 7px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
}

.lux-appconfig-hero__popover--overridden .lux-appconfig-hero__popover-head .fe {
    color: #0e7490;
    background: rgba(14, 116, 144, 0.1);
}

.lux-appconfig-hero__popover--locked .lux-appconfig-hero__popover-head .fe {
    color: #b45309;
    background: rgba(245, 158, 11, 0.12);
}

.lux-appconfig-hero__popover-head strong {
    display: block;
    font-size: 0.75rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.2;
}

.lux-appconfig-hero__popover-head span {
    display: block;
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
}

.lux-appconfig-hero__popover-empty {
    margin: 0;
    padding: 0.65rem;
    font-size: 0.6875rem;
    line-height: 1.45;
    color: #64748b;
}

.lux-appconfig-hero__popover-list {
    margin: 0;
    padding: 0.35rem;
    list-style: none;
    overflow-y: auto;
}

.lux-appconfig-hero__popover-list-item {
    padding: 0.4rem 0.45rem;
    border-radius: 7px;
}

.lux-appconfig-hero__popover-list-item:hover {
    background: #f8fafc;
}

.lux-appconfig-hero__popover-module {
    display: block;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
    line-height: 1.3;
}

.lux-appconfig-hero__popover-setting {
    display: block;
    font-size: 0.6875rem;
    font-weight: 600;
    color: #0f172a;
    line-height: 1.35;
}

.lux-appconfig-hero__guide-lead {
    margin: 0 0 0.45rem;
    font-size: 0.75rem;
    line-height: 1.45;
    color: #475569;
    font-weight: 600;
}

.lux-appconfig-hero__tips {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 0.25rem 0.75rem;
    margin: 0;
    padding: 0;
    list-style: none;
}

.lux-appconfig-hero__tips li {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.6875rem;
    line-height: 1.35;
    color: #64748b;
}

.lux-appconfig-hero__tips i {
    flex-shrink: 0;
    width: 18px;
    color: var(--lux-primary, #5b5ff4);
    font-size: 0.75rem;
}

/* —— Layout —— */
.lux-appconfig__layout {
    display: grid;
    grid-template-columns: minmax(300px, 360px) minmax(0, 1fr);
    gap: 6px;
    align-items: stretch;
    flex: 1;
    min-height: 0;
}

.lux-appconfig__sidebar {
    display: flex;
    flex-direction: column;
    position: relative;
    top: auto;
    min-height: 0;
    max-height: none;
    height: 100%;
}

.lux-appconfig__main {
    min-width: 0;
    display: flex;
    flex-direction: column;
    min-height: 0;
    overflow: hidden;
}

.lux-appconfig-panel {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
}

/* —— Configuration navigator (unified tree sidebar) —— */
.lux-ac-nav {
    --ac-tree-select-accent: #0e7490;
    --ac-tree-select-accent-bright: #06b6d4;
    --ac-tree-select-bg: rgba(14, 116, 144, 0.1);
    --ac-tree-select-text: #0c4a6e;
    display: flex;
    flex-direction: column;
    height: 100%;
    min-height: 0;
    border-radius: var(--lux-ac-radius);
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: #fff;
    box-shadow: 0 8px 24px rgba(15, 23, 42, 0.05);
    overflow: hidden;
}

.lux-ac-nav__header {
    padding: 0.65rem 0.75rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
    background: #fafbfc;
}

.lux-ac-nav__title {
    margin: 0;
    font-size: 0.8125rem;
    font-weight: 800;
    letter-spacing: -0.01em;
    color: #0f172a;
}

.lux-ac-nav__tabs {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.25rem;
    padding: 0.45rem 0.55rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
    background: #f8fafc;
}

.lux-ac-nav__tab {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.3rem;
    min-height: 32px;
    padding: 0.3rem 0.45rem;
    border: 1px solid transparent;
    border-radius: 11px;
    background: transparent;
    font-size: 0.6875rem;
    font-weight: 700;
    color: #64748b;
    cursor: pointer;
    transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
}

.lux-ac-nav__tab:hover {
    color: #334155;
    background: #fff;
    border-color: #e2e8f0;
}

.lux-ac-nav__tab.is-active {
    color: #fff;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
    border-color: transparent;
    box-shadow: 0 6px 16px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}

.lux-ac-nav__tab-count {
    min-width: 1.25rem;
    height: 1.25rem;
    padding: 0 0.3rem;
    border-radius: 9911px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    font-weight: 800;
    background: rgba(15, 23, 42, 0.08);
}

.lux-ac-nav__tab.is-active .lux-ac-nav__tab-count {
    background: rgba(255, 255, 255, 0.22);
}

.lux-ac-nav__toolbar {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.45rem 0.55rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
}

.lux-ac-nav__search {
    flex: 1;
    display: flex;
    align-items: center;
    gap: 0.35rem;
    min-width: 0;
    padding: 0 0.625rem;
    height: 32px;
    border-radius: 8px;
    border: 1px solid #e2e8f0;
    background: #fff;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.lux-ac-nav__search:focus-within {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.4);
    box-shadow: 0 0 0 3px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-ac-nav__search i {
    color: #94a3b8;
    font-size: 0.875rem;
    flex-shrink: 0;
}

.lux-ac-nav__search input {
    flex: 1;
    min-width: 0;
    border: none;
    background: transparent;
    font-size: 0.8125rem;
    color: #0f172a;
    outline: none;
}

.lux-ac-nav__search input::placeholder {
    color: #94a3b8;
}

.lux-ac-nav__search-clear {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 22px;
    height: 22px;
    padding: 0;
    border: none;
    border-radius: 9911px;
    background: #f1f5f9;
    color: #64748b;
    cursor: pointer;
}

.lux-ac-nav__add,
.lux-ac-nav__icon-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    padding: 0;
    border: none;
    border-radius: 8px;
    font-size: 0.8125rem;
    color: #64748b;
    background: #f1f5f9;
    cursor: pointer;
    flex-shrink: 0;
    transition: background 0.15s ease, color 0.15s ease;
}

.lux-ac-nav__add {
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-ac-nav__add:hover,
.lux-ac-nav__icon-btn:hover {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14);
    color: var(--lux-primary, #5b5ff4);
}

.lux-ac-nav__selection {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.35rem 0.55rem;
    margin: 0.35rem 0.55rem 0;
    border-radius: 8px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.07);
    border: 1px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    font-size: 0.6875rem;
    color: #64748b;
    min-width: 0;
}

.lux-ac-nav__selection strong {
    color: #0f172a;
    font-weight: 700;
    font-size: 0.75rem;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    min-width: 0;
}

.lux-ac-nav__tree-wrap {
    flex: 1;
    min-height: 0;
    overflow: auto;
    padding: 0.25rem 0.35rem 0.45rem;
    overscroll-behavior: contain;
}

.lux-ac-nav__footer {
    padding: 0.4rem 0.65rem;
    border-top: 1px solid #e2e8f0;
    background: #f8fafc;
    font-size: 0.75rem;
    font-weight: 600;
    color: #94a3b8;
}

/* —— Compact tree: single-level indent only (no depth stacking) —— */
.lux-ac-tree {
    display: flex;
    flex-direction: column;
    gap: 1px;
    min-width: 100%;
}

.lux-ac-tree-branch,
.lux-ac-tree-node {
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.lux-ac-tree-children {
    margin-left: 12px;
    padding-left: 8px;
    border-left: 1px solid rgba(148, 163, 184, 0.35);
}

.lux-ac-tree-row {
    position: relative;
    display: flex;
    align-items: center;
    gap: 2px;
    min-height: 30px;
    padding: 1px 4px 1px 2px;
    border-radius: 8px;
    transition: background 0.12s ease, box-shadow 0.12s ease;
}

.lux-ac-tree-row:hover {
    background: #f1f5f9;
}

/* Tree selection — ring + solid icon + right check (not main-menu left bar) */
.lux-ac-tree-row.is-selected {
    padding-right: 22px;
    background: rgba(14, 116, 144, 0.07);
    box-shadow:
        0 0 0 1.5px rgba(14, 116, 144, 0.32),
        inset 0 1px 0 rgba(255, 255, 255, 0.55);
}

.lux-ac-tree-row.is-selected::after {
    content: "✓";
    position: absolute;
    right: 5px;
    top: 50%;
    transform: translateY(-50%);
    width: 15px;
    height: 15px;
    border-radius: 50%;
    background: linear-gradient(145deg, #0e7490 0%, #06b6d4 100%);
    color: #fff;
    font-size: 8px;
    font-weight: 800;
    line-height: 15px;
    text-align: center;
    box-shadow: 0 2px 5px rgba(14, 116, 144, 0.28);
    pointer-events: none;
}

.lux-ac-tree-row.is-selected .lux-ac-tree-name {
    font-weight: 700;
    color: var(--ac-tree-select-text);
}

.lux-ac-tree-row.is-selected .lux-ac-tree-icon--org,
.lux-ac-tree-row.is-selected .lux-ac-tree-icon--role {
    color: #fff;
    background: linear-gradient(145deg, #0e7490 0%, #06b6d4 100%);
    box-shadow: 0 2px 6px rgba(14, 116, 144, 0.22);
}

.lux-ac-tree-row.is-selected .lux-ac-tree-toggle {
    color: var(--ac-tree-select-accent);
}

.lux-ac-tree-row.is-selected .lux-ac-tree-badge {
    color: #0e7490;
    background: rgba(6, 182, 212, 0.12);
    border-color: rgba(14, 116, 144, 0.24);
}

.lux-ac-tree-row.is-disabled {
    opacity: 0.45;
}

.lux-ac-tree-toggle {
    flex-shrink: 0;
    width: 20px;
    height: 28px;
    margin: 0;
    padding: 0;
    border: none;
    border-radius: 6px;
    background: transparent;
    color: #64748b;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    transition: background 0.12s ease, color 0.12s ease;
}

.lux-ac-tree-toggle:hover {
    background: #e2e8f0;
    color: var(--lux-primary, #5b5ff4);
}

.lux-ac-tree-toggle.is-open i {
    transform: rotate(90deg);
}

.lux-ac-tree-toggle--spacer {
    width: 20px;
    flex-shrink: 0;
    pointer-events: none;
}

.lux-ac-tree-label {
    flex: 1;
    min-width: 0;
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 2px 4px 2px 0;
    border: none;
    background: transparent;
    text-align: left;
    cursor: pointer;
    border-radius: 6px;
}

.lux-ac-tree-label:disabled {
    cursor: not-allowed;
}

.lux-ac-tree-icon {
    flex-shrink: 0;
    width: 22px;
    height: 22px;
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.6875rem;
}

.lux-ac-tree-icon--org {
    color: var(--lux-primary, #5b5ff4);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-ac-tree-icon--role {
    color: #0d9488;
    background: rgba(20, 184, 166, 0.12);
}

.lux-ac-tree-copy {
    flex: 1;
    min-width: 0;
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 4px;
}

.lux-ac-tree-name {
    font-size: 0.75rem;
    font-weight: 600;
    color: #0f172a;
    line-height: 1.25;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    max-width: 100%;
}

.lux-ac-tree-badge {
    flex-shrink: 0;
    font-size: 0.6875rem;
    font-weight: 700;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    padding: 0.05rem 0.35rem;
    border-radius: 9911px;
    color: #64748b;
    background: #f1f5f9;
    border: 1px solid #e2e8f0;
    line-height: 1.35;
}

.lux-ac-tree-current {
    flex-shrink: 0;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    padding: 0.05rem 0.35rem;
    border-radius: 9911px;
    color: #047857;
    background: #d1fae5;
    line-height: 1.35;
}

.lux-ac-tree-create {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    margin: 2px 0 4px 28px;
    padding: 0.25rem;
    border-radius: 8px;
    background: #f8fafc;
    border: 1px dashed rgba(148, 163, 184, 0.4);
}

.lux-ac-tree-create__input {
    flex: 1;
    min-width: 0;
    height: 28px;
    padding: 0 0.625rem;
    border-radius: 6px;
    border: 1px solid #e2e8f0;
    font-size: 0.75rem;
    background: #fff;
}

.lux-ac-tree-create__input:focus {
    outline: none;
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.45);
    box-shadow: 0 0 0 3px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-ac-tree-create__btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 30px;
    height: 30px;
    padding: 0;
    border: none;
    border-radius: 8px;
    background: #e2e8f0;
    color: #64748b;
    cursor: pointer;
}

.lux-ac-tree-create__btn--save:not(:disabled) {
    color: #fff;
    background: var(--lux-primary, #5b5ff4);
}

.lux-ac-tree-create__btn:disabled {
    opacity: 0.45;
    cursor: not-allowed;
}

.lux-ac-tree-empty {
    margin: 1rem 0.75rem;
    font-size: 0.8125rem;
    color: #64748b;
    text-align: center;
}

/* Legacy tree panel styles removed — use lux-ac-nav above */

/* —— Empty state —— */
.lux-appconfig-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 420px;
    padding: 1.5rem 1rem;
    border-radius: var(--lux-ac-radius);
