/* Add line modal */
.lux-estimate-line-modal {
    position: fixed;
    inset: 0;
    z-index: 1000002;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
}

.lux-estimate-line-modal__backdrop {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.45);
    backdrop-filter: blur(4px);
}

.lux-estimate-line-modal__panel {
    position: relative;
    width: min(520px, 100%);
    max-height: 90vh;
    overflow-y: auto;
    border-radius: var(--pd-radius);
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: #fff;
    box-shadow: 0 32px 80px rgba(15, 23, 42, 0.2);
}

.lux-estimate-line-modal__head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 12px;
    padding: 20px 22px 0;
}

.lux-estimate-line-modal__kicker {
    display: block;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-estimate-line-modal__title {
    margin: 4px 0 0;
    font-size: 18px;
    font-weight: 800;
    color: #0f172a;
}

.lux-estimate-line-modal__form {
    padding: 18px 22px 22px;
}

.lux-estimate-form-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
}

.lux-estimate-field--wide {
    grid-column: 1 / -1;
}

.lux-estimate-field__label {
    display: block;
    margin-bottom: 6px;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-estimate-input {
    border-radius: 12px !important;
    border: 1px solid #e2e8f0 !important;
    font-weight: 600;
}

.lux-estimate-line-modal__foot {
    display: flex;
    justify-content: flex-end;
    gap: 12px;
    margin-top: 18px;
    padding-top: 16px;
    border-top: 1px solid #f1f5f9;
}

@media (max-width: 767px) {
    .lux-estimate-form-grid {
        grid-template-columns: 1fr;
    }

    .lux-estimate-line {
        grid-template-columns: 1fr repeat(3, 48px);
