/* ========== Checklist — luxury panel & editor ========== */

.pd-checklist {
    padding: 18px 20px;
    border-radius: var(--pd-radius);
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: rgba(255, 255, 255, 0.9);
    box-shadow: 0 16px 40px rgba(15, 23, 42, 0.05);
}

.pd-checklist__head {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    margin-bottom: 14px;
}

.pd-checklist__icon {
    width: 34px;
    height: 34px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: rgba(16, 185, 129, 0.12);
    color: #059669;
    flex-shrink: 0;
}

.pd-checklist__titles {
    flex: 1;
    min-width: 0;
}

.pd-checklist__title {
    margin: 0;
    font-size: 15px;
    font-weight: 800;
    color: #1e293b;
}

.pd-checklist__subtitle {
    margin: 2px 0 0;
    font-size: 12px;
    color: #94a3b8;
}

.pd-checklist__stats {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 14px;
    margin-bottom: 12px;
    border-radius: var(--pd-radius-sm);
    background: linear-gradient(135deg, rgba(16, 185, 129, 0.06), rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06));
    border: 1px solid rgba(16, 185, 129, 0.15);
}

.pd-checklist__ring {
    position: relative;
    width: 52px;
    height: 52px;
    flex-shrink: 0;
}

.pd-checklist__ring svg {
    width: 100%;
    height: 100%;
    transform: rotate(-90deg);
}

.pd-checklist__ring-bg {
    fill: none;
    stroke: #e2e8f0;
    stroke-width: 3;
}

.pd-checklist__ring-fill {
    fill: none;
    stroke: var(--lux-primary, #5b5ff4);
    stroke-width: 3;
    stroke-linecap: round;
    transition: stroke-dasharray 0.4s ease;
}

.pd-checklist__ring.is-complete .pd-checklist__ring-fill {
    stroke: #10b981;
}

.pd-checklist__ring-label {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    font-weight: 800;
    color: #334155;
}

.pd-checklist__stat-copy strong {
    display: block;
    font-size: 16px;
    font-weight: 800;
    color: #1e293b;
}

.pd-checklist__stat-copy span {
    display: block;
    font-size: 12px;
    color: #64748b;
}

.pd-checklist__mandatory {
    margin-top: 4px;
    font-weight: 600;
    color: #d97706 !important;
}

.pd-checklist__empty {
    text-align: center;
    padding: 16px 8px;
    color: #94a3b8;
}

.pd-checklist__empty i {
    display: block;
    font-size: 26px;
    margin-bottom: 8px;
    opacity: 0.5;
}

.pd-checklist__empty p {
    margin: 0 0 12px;
    font-size: 13px;
}

.pd-checklist__preview {
    list-style: none;
    margin: 0 0 12px;
    padding: 0;
}

.pd-checklist__preview-item {
    display: grid;
    grid-template-columns: 18px 1fr auto;
    gap: 8px;
    align-items: start;
    padding: 8px 0;
    border-bottom: 1px solid #f1f5f9;
    font-size: 12px;
}

.pd-checklist__preview-item i {
    color: #cbd5e1;
    margin-top: 2px;
}

.pd-checklist__preview-item.is-done i {
    color: #10b981;
}

.pd-checklist__preview-q {
    color: #475569;
    font-weight: 600;
    line-height: 1.35;
}

.pd-checklist__preview-a {
    color: #94a3b8;
    font-size: 12px;
    font-weight: 600;
    text-align: right;
    max-width: 80px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.pd-checklist__preview-more {
    padding: 8px 0 0;
    font-size: 12px;
    font-weight: 700;
    color: var(--lux-primary, #5b5ff4);
}

.pd-checklist__configure {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin-top: 4px;
    font-size: 12px;
    font-weight: 700;
    color: #64748b !important;
}

.pd-checklist__configure:hover {
    color: var(--lux-primary, #5b5ff4) !important;
}

.pd-checklist__status-badge {
    display: inline-block;
    padding: 4px 12px;
    border-radius: 9911px;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #d97706;
    background: #fffbeb;
    border: 1px solid #fde68a;
}

.pd-checklist__status-badge.is-complete {
    color: #059669;
    background: #ecfdf5;
    border-color: #a7f3d0;
}

