    font-weight: 700;
    color: #334155;
    white-space: nowrap;
    letter-spacing: -0.01em;
}

.lux-ts-header__live {
    padding: 0.12rem 0.38rem;
    border-radius: 9911px;
    background: rgba(5, 150, 105, 0.12);
