    font-weight: 800;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: #047857;
    flex-shrink: 0;
}

.lux-ts-header__week-divider {
    width: 1px;
    height: 1.25rem;
    background: rgba(226, 232, 240, 0.95);
    flex-shrink: 0;
}

.lux-ts-header__nav {
    display: inline-flex;
    align-items: center;
    gap: 0.08rem;
    padding: 0.1rem;
    flex-shrink: 0;
}

.lux-ts-header__nav-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.625rem;
    height: 1.625rem;
    padding: 0;
    border: none;
    border-radius: 9911px;
    background: transparent;
    color: #64748b;
    font-size: 0.6875rem;
    cursor: pointer;
    transition: background 0.14s ease, color 0.14s ease;
}

.lux-ts-header__nav-btn:hover:not(:disabled) {
