.lux-emp-card__body {
    position: relative;
    z-index: 1;
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.55rem;
    padding: 0 0.85rem 0.65rem;
    min-width: 0;
}

.lux-emp-card__identity {
    width: 100%;
    min-width: 0;
}

.lux-emp-card__name {
    margin: 0;
    font-size: 1rem;
    font-weight: 800;
    line-height: 1.25;
    color: #0f172a;
}

.lux-emp-card__name a {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.25rem;
    max-width: 100%;
    color: inherit;
