}

.lux-emp-card__facts:has(.lux-emp-card__fact:only-child) {
    grid-template-columns: 1fr;
}

.lux-emp-card__fact:last-child:nth-child(odd):not(:only-child) {
    grid-column: 1 / -1;
}

.lux-emp-card__fact {
    display: flex;
    align-items: flex-start;
