    background: rgba(239, 68, 68, 0.1);
}

.lux-emp-card__fact-copy {
    display: flex;
    flex-direction: column;
    gap: 0.04rem;
    min-width: 0;
}

.lux-emp-card__fact-copy > span {
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-emp-card__fact-copy strong {
    font-size: 0.75rem;
    font-weight: 700;
    color: #334155;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-emp-card__fact.is-danger .lux-emp-card__fact-copy strong {
    color: #dc2626;
}

.lux-emp-card__footer {
    position: relative;
    z-index: 2;
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    margin-top: auto;
    padding: 0.55rem 0.85rem 0.75rem;
    border-top: 1px solid rgba(226, 232, 240, 0.9);
    background: linear-gradient(180deg, rgba(248, 250, 252, 0.4), rgba(248, 250, 252, 0.85));
}

.lux-emp-card__contact {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    min-width: 0;
    min-height: 1.75rem;
    padding: 0.3rem 0.55rem;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.88);
    font-size: 0.75rem;
    font-weight: 600;
    color: #475569;
    text-decoration: none;
    transition: border-color 0.14s ease, color 0.14s ease, background 0.14s ease;
}

.lux-emp-card__contact:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-emp-card__contact i {
    flex-shrink: 0;
    font-size: 0.75rem;
    color: var(--lux-primary, #5b5ff4);
}

.lux-emp-card__contact span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    min-width: 0;
}

.lux-emp-card__overlay {
    position: absolute;
    inset: 0;
    z-index: 3;
    display: grid;
    place-items: center;
    background: rgba(248, 250, 252, 0.55);
    pointer-events: none;
}

.lux-emp-card__overlay span {
    padding: 0.35rem 0.85rem;
    border: 1px dashed rgba(148, 163, 184, 0.8);
    border-radius: 9911px;
    background: rgba(255, 255, 255, 0.88);
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-emp-card.is-deleted .lux-emp-card__overlay span {
    color: #dc2626;
    border-color: rgba(239, 68, 68, 0.35);
}

@media (prefers-reduced-motion: reduce) {
    .lux-emp-grid__item {
        animation: none;
    }

    .lux-emp-card,
    .lux-emp-card__avatar-link,
    .lux-emp-card__name a i {
        transition: none;
    }
}

@media (max-width: 767px) {
    .lux-emp-grid {
        grid-template-columns: 1fr;
        gap: 0.85rem;
        padding: 0.55rem;
    }

    .lux-emp-card__facts {
        grid-template-columns: 1fr;
    }
}

