    margin: 0.75rem;
    padding: 2rem 1rem;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 18px;
    background: rgba(255, 255, 255, 0.96);
    box-shadow: 0 8px 24px rgba(15, 23, 42, 0.06);
    text-align: center;
}

.lux-inv-detail__denied i {
    font-size: 1.5rem;
    color: #94a3b8;
}

.lux-inv-detail__denied strong {
    font-size: 0.9375rem;
    color: #334155;
}

.lux-inv-detail__denied p {
    margin: 0;
    font-size: 0.6875rem;
    color: #64748b;
}

/* Invoice sheet — full bleed */

.lux-inv-detail__sheet {
    overflow: visible;
    width: 100%;
    min-height: auto;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-top: none;
    border-radius: 0 0 18px 18px;
    background: #ffffff;
    box-shadow: 0 8px 24px rgba(15, 23, 42, 0.06);
}

.lux-inv-detail--fullpage:not(:has(.lux-inv-detail__toolbar)) .lux-inv-detail__sheet {
    border-top: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 18px;
}

.lux-inv-detail__accent {
    height: 0.28rem;
    background: linear-gradient(
        90deg,
        var(--lux-primary, #5b5ff4) 0%,
        #059669 50%,
        #7c3aed 100%
    );
}

.lux-inv-detail__sheet-body {
    padding: 0 0 1.5rem;
}

.lux-inv-detail__sheet--loading {
    padding: 1.25rem;
    min-height: 20rem;
}

.lux-inv-detail__brand {
    position: relative;
    padding: 1rem 1.75rem 0.85rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
    background:
        radial-gradient(ellipse at 15% 0%, rgba(167, 139, 250, 0.28), transparent 52%),
        radial-gradient(ellipse at 85% 100%, rgba(16, 185, 129, 0.2), transparent 48%),
        linear-gradient(125deg, #0b1220 0%, #162032 45%, #1e1b4b 100%);
    color: #f8fafc;
}

.lux-inv-detail__brand::after {
    content: "";
    position: absolute;
    left: 1.75rem;
    right: 1.75rem;
    bottom: 0;
    height: 1px;
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.22) 20%,
        rgba(110, 231, 183, 0.45) 50%,
        rgba(255, 255, 255, 0.22) 80%,
        transparent
    );
}

.lux-inv-detail__brand-top {
    margin-bottom: 0.65rem;
}

.lux-inv-detail__brand-main {
    display: flex;
    align-items: center;
    gap: 0.85rem;
}

.lux-inv-detail__logo-wrap {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 3.75rem;
    height: 3.75rem;
    border-radius: 16px;
    background: rgba(255, 255, 255, 0.96);
    box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.12),
        0 12px 24px rgba(0, 0, 0, 0.18);
    flex-shrink: 0;
}

.lux-inv-detail__logo {
    width: 2.65rem;
    height: auto;
}

.lux-inv-detail__brand-copy {
    min-width: 0;
}

.lux-inv-detail__brand-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    margin-bottom: 0.18rem;
    padding: 0.12rem 0.45rem;
    border-radius: 9911px;
    background: rgba(255, 255, 255, 0.08);
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: rgba(226, 232, 240, 0.88);
}

.lux-inv-detail__supplier-name {
    margin: 0;
    font-size: 1.125rem;
    font-weight: 900;
    color: #ffffff;
    line-height: 1.15;
    letter-spacing: -0.02em;
}

.lux-inv-detail__subsidiary-note {
    margin: 0.2rem 0 0;
    font-size: 0.6875rem;
    font-weight: 500;
    letter-spacing: 0.03em;
    line-height: 1.4;
    color: rgba(203, 213, 225, 0.65);
}

.lux-inv-detail__supplier-reg {
    margin: 0.15rem 0 0;
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: rgba(167, 243, 208, 0.88);
}

.lux-inv-detail__supplier-line {
    margin: 0.2rem 0 0;
    font-size: 0.6875rem;
    font-weight: 500;
    line-height: 1.45;
    color: rgba(203, 213, 225, 0.88);
}

.lux-inv-detail__brand-contacts {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem;
}

.lux-inv-detail__contact-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.32rem;
    min-height: 1.65rem;
    padding: 0 0.55rem;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 9911px;
    background: rgba(255, 255, 255, 0.07);
    backdrop-filter: blur(8px);
    font-size: 0.75rem;
    font-weight: 600;
    color: rgba(241, 245, 249, 0.94);
}

.lux-inv-detail__contact-chip i {
    font-size: 0.6875rem;
    color: #6ee7b7;
}

.lux-inv-detail__contact-chip.is-muted {
    color: rgba(203, 213, 225, 0.82);
}

.lux-inv-detail__contact-chip.is-muted i {
    color: rgba(196, 181, 253, 0.95);
}

.lux-inv-detail__hero {
    display: grid;
    grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.9fr);
    gap: 0.85rem;
    padding: 1rem 1.75rem 0.85rem;
    background: linear-gradient(180deg, rgba(248, 250, 252, 0.85), rgba(255, 255, 255, 0));
}

.lux-inv-detail__section-label {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    margin-bottom: 0.35rem;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-inv-detail__section-label i {
    color: var(--lux-primary, #5b5ff4);
}

.lux-inv-detail__bill-to h2 {
    margin: 0;
    font-size: 1rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-inv-detail__bill-reg,
.lux-inv-detail__bill-line {
    margin: 0.12rem 0 0;
    font-size: 0.6875rem;
    font-weight: 600;
    line-height: 1.45;
    color: #475569;
}

.lux-inv-detail__bill-links {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    margin-top: 0.55rem;
}

.lux-inv-detail__bill-links a,
.lux-inv-detail__bill-links span {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.6875rem;
    font-weight: 700;
    color: #334155;
    text-decoration: none;
}

.lux-inv-detail__bill-links a:hover {
    color: var(--lux-primary-dark, #3730a3);
}

.lux-inv-detail__bill-links i {
    color: #059669;
}

.lux-inv-detail__summary-title {
    margin-bottom: 0.4rem;
    font-size: 2rem;
    font-weight: 900;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: rgba(148, 163, 184, 0.32);
    line-height: 1;
    text-align: right;
}

.lux-inv-detail__summary-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.45rem;
}

.lux-inv-detail__summary-card {
    display: flex;
    flex-direction: column;
    gap: 0.08rem;
    padding: 0.65rem 0.75rem;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.92);
}

.lux-inv-detail__summary-card span {
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-inv-detail__summary-card strong {
    font-size: 0.9375rem;
    font-weight: 900;
    color: #0f172a;
    line-height: 1.2;
}

.lux-inv-detail__summary-card.is-primary {
    grid-column: 1 / -1;
    border-color: rgba(5, 150, 105, 0.22);
    background: linear-gradient(135deg, rgba(16, 185, 129, 0.12), rgba(255, 255, 255, 0.96));
}

.lux-inv-detail__summary-card.is-primary strong {
    font-size: 1.375rem;
    color: #047857;
}

.lux-inv-detail__summary-card.is-status.is-blue {
    border-color: rgba(37, 99, 235, 0.2);
    background: rgba(37, 99, 235, 0.06);
}

.lux-inv-detail__summary-card.is-status.is-amber {
    border-color: rgba(217, 119, 6, 0.2);
    background: rgba(217, 119, 6, 0.06);
}

.lux-inv-detail__summary-card.is-status.is-green {
    border-color: rgba(5, 150, 105, 0.2);
    background: rgba(5, 150, 105, 0.06);
}

.lux-inv-detail__summary-card.is-status.is-violet {
    border-color: rgba(124, 58, 237, 0.2);
    background: rgba(124, 58, 237, 0.06);
}

.lux-inv-detail__summary-card.is-status.is-slate {
    border-color: rgba(100, 116, 139, 0.2);
    background: rgba(100, 116, 139, 0.06);
}

/* Line items */

.lux-inv-detail__items {
    margin: 0 1.75rem;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 16px;
    overflow: hidden;
    background: rgba(255, 255, 255, 0.98);
    box-shadow: 0 8px 24px rgba(15, 23, 42, 0.04);
}

.lux-inv-detail__items-head,
.lux-inv-detail__item-row {
    display: grid;
    grid-template-columns: minmax(0, 2fr) minmax(5rem, 0.75fr) minmax(3.5rem, 0.45fr) minmax(6rem, 0.75fr);
    gap: 0.55rem;
    align-items: center;
}

.lux-inv-detail__items-head {
    padding: 0.55rem 0.85rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.95);
    background: rgba(248, 250, 252, 0.96);
}

.lux-inv-detail__items-head span {
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-inv-detail__items-head span:not(:first-child),
.lux-inv-detail__item-row > div:not(:first-child) {
    text-align: center;
}

.lux-inv-detail__item-row {
    padding: 0.65rem 0.85rem;
    border-bottom: 1px solid rgba(241, 245, 249, 0.98);
    font-size: 0.75rem;
    font-weight: 700;
    color: #334155;
}

.lux-inv-detail__item-row:last-child {
    border-bottom: none;
}

.lux-inv-detail__item-row:nth-child(even) {
    background: rgba(248, 250, 252, 0.72);
}

.lux-inv-detail__item-desc strong {
    display: block;
    font-size: 0.8125rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-inv-detail__item-desc p {
    margin: 0.18rem 0 0;
    font-size: 0.6875rem;
    font-weight: 600;
    line-height: 1.45;
    color: #64748b;
}

.lux-inv-detail__item-total {
    font-size: 0.8125rem !important;
    font-weight: 900 !important;
    color: #047857 !important;
}

/* Settlement */

.lux-inv-detail__settlement {
    display: grid;
    grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
    gap: 0.85rem;
    padding: 0.85rem 1.75rem 1rem;
}

.lux-inv-detail__payment h3,
.lux-inv-detail__terms h3 {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    margin: 0 0 0.45rem;
    font-size: 0.8125rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-inv-detail__payment h3 i {
    color: var(--lux-primary, #5b5ff4);
}

.lux-inv-detail__payment-method {
    margin: 0 0 0.65rem;
    font-size: 0.75rem;
    font-weight: 800;
    color: #334155;
}

.lux-inv-detail__tax-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.35rem;
    margin-bottom: 0.55rem;
}

.lux-inv-detail__tax-grid span {
    display: block;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-inv-detail__tax-grid strong {
    display: block;
    font-size: 0.6875rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-inv-detail__bank-card {
    padding: 0.75rem;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    background: linear-gradient(180deg, rgba(248, 250, 252, 0.96), rgba(255, 255, 255, 0.98));
}

.lux-inv-detail__bank-label {
    display: block;
    margin-bottom: 0.15rem;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-inv-detail__bank-card strong {
    display: block;
    font-size: 0.8125rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-inv-detail__bank-card p {
    margin: 0.12rem 0 0;
    font-size: 0.6875rem;
    font-weight: 600;
    line-height: 1.45;
    color: #475569;
}

.lux-inv-detail__totals-rows {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    margin-bottom: 0.55rem;
}

.lux-inv-detail__totals-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.55rem;
    padding: 0.35rem 0;
    border-bottom: 1px dashed rgba(226, 232, 240, 0.95);
    font-size: 0.75rem;
    color: #475569;
}

.lux-inv-detail__totals-row strong {
    font-size: 0.8125rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-inv-detail__totals-row.is-discount strong {
    color: #dc2626;
}

.lux-inv-detail__totals-due {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.55rem;
    padding: 0.75rem 0.85rem;
    border-radius: 14px;
    background: linear-gradient(135deg, #059669, #047857);
    color: #fff;
}

.lux-inv-detail__totals-due span {
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.lux-inv-detail__totals-due strong {
    font-size: 1.25rem;
    font-weight: 900;
}

.lux-inv-detail__signature {
    margin-top: 0.65rem;
    text-align: center;
}

.lux-inv-detail__signature img {
    width: 5.5rem;
    max-width: 40%;
    margin-bottom: 0.35rem;
}

.lux-inv-detail__signature p {
    margin: 0;
    font-size: 0.75rem;
    font-weight: 700;
    color: #334155;
}

.lux-inv-detail__signature strong {
    font-size: 0.6875rem;
    font-weight: 800;
    color: #64748b;
}

.lux-inv-detail__terms {
    padding: 0 1.75rem 1rem;
}

.lux-inv-detail__terms p {
    margin: 0;
    padding: 0.65rem 0.75rem;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.88);
    font-size: 0.6875rem;
    line-height: 1.5;
    color: #475569;
}

.lux-inv-detail__footer {
    display: grid;
    grid-template-columns: minmax(0, 1.2fr) repeat(3, minmax(0, 0.8fr));
    gap: 0.55rem;
    align-items: center;
    padding: 0.75rem 1.75rem 1rem;
    border-top: 1px solid rgba(226, 232, 240, 0.95);
    background: linear-gradient(180deg, #f8fafc, #f1f5f9);
}

.lux-inv-detail__footer img {
    width: 3rem;
    height: auto;
}

.lux-inv-detail__footer div {
    display: flex;
    flex-direction: column;
    gap: 0.08rem;
    padding-left: 0.55rem;
    border-left: 1px solid rgba(226, 232, 240, 0.95);
}

.lux-inv-detail__footer span {
    font-size: 0.75rem;
    font-weight: 600;
    line-height: 1.35;
    color: #64748b;
}

/* Billed employees modal */

body.lux-inv-emp-modal-open {
    overflow: hidden;
}

.lux-inv-emp-modal {
    position: fixed;
    inset: 0;
    z-index: 1200;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}

.lux-inv-emp-modal__backdrop {
    position: absolute;
    inset: 0;
    border: none;
    background: rgba(15, 23, 42, 0.52);
    backdrop-filter: blur(6px);
    cursor: pointer;
}

.lux-inv-emp-modal__dialog {
    position: relative;
    z-index: 1;
    display: flex;
    flex-direction: column;
    width: min(640px, 100%);
    max-height: min(82vh, 720px);
    border: 1px solid rgba(226, 232, 240, 0.98);
    border-radius: 20px;
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08), transparent 42%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.98));
    box-shadow: 0 24px 64px rgba(15, 23, 42, 0.22);
    overflow: hidden;
}

.lux-inv-emp-modal__header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.65rem;
    padding: 1rem 1rem 0.75rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.95);
}

.lux-inv-emp-modal__header-main {
    display: flex;
    align-items: flex-start;
    gap: 0.65rem;
    min-width: 0;
}

.lux-inv-emp-modal__icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 14px;
    background: linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16), rgba(16, 185, 129, 0.14));
    color: var(--lux-primary, #5b5ff4);
    flex-shrink: 0;
}

.lux-inv-emp-modal__eyebrow {
    display: block;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-inv-emp-modal__header h2 {
    margin: 0.08rem 0 0;
    font-size: 1rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-inv-emp-modal__header p {
    margin: 0.15rem 0 0;
    font-size: 0.75rem;
    font-weight: 700;
    color: #64748b;
}

.lux-inv-emp-modal__close {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border: 1px solid #e2e8f0;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.95);
    color: #64748b;
    cursor: pointer;
    flex-shrink: 0;
    transition: all 0.14s ease;
}

.lux-inv-emp-modal__close:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.24);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-inv-emp-modal__search-wrap {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.65rem 1rem;
}

.lux-inv-emp-modal__search {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    flex: 1;
    min-height: 2.25rem;
    padding: 0 0.65rem;
    border: 1px solid #e2e8f0;
    border-radius: 9911px;
    background: rgba(255, 255, 255, 0.96);
}

.lux-inv-emp-modal__search i {
    color: #94a3b8;
    flex-shrink: 0;
}

.lux-inv-emp-modal__search input {
    flex: 1;
    min-width: 0;
    border: none;
    background: transparent;
    font-size: 0.6875rem;
    font-weight: 600;
    color: #0f172a;
    outline: none;
}

.lux-inv-emp-modal__search-clear {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.25rem;
    height: 1.25rem;
    border: none;
    border-radius: 9911px;
    background: rgba(148, 163, 184, 0.16);
    color: #64748b;
    cursor: pointer;
}

.lux-inv-emp-modal__count-pill {
    flex-shrink: 0;
    min-height: 2rem;
    padding: 0 0.55rem;
    border-radius: 9911px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    font-size: 0.6875rem;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
    display: inline-flex;
    align-items: center;
}

.lux-inv-emp-modal__list {
    flex: 1;
    overflow: auto;
    padding: 0 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}

.lux-inv-emp-modal__row {
    display: grid;
    grid-template-columns: auto 1fr auto;
    gap: 0.55rem;
    align-items: center;
    padding: 0.6rem 0.65rem;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.94);
    transition: border-color 0.14s ease, box-shadow 0.14s ease;
}

.lux-inv-emp-modal__row:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    box-shadow: 0 4px 14px rgba(15, 23, 42, 0.05);
}

.lux-inv-emp-modal__avatar {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.125rem;
    height: 2.125rem;
    border-radius: 12px;
    background: linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14), rgba(16, 185, 129, 0.12));
    font-size: 0.6875rem;
    font-weight: 900;
    color: var(--lux-primary-dark, #3730a3);
}

.lux-inv-emp-modal__row-copy strong {
    display: block;
    font-size: 0.75rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-inv-emp-modal__row-copy a {
    display: block;
    margin-top: 0.05rem;
    font-size: 0.75rem;
    font-weight: 700;
    color: var(--lux-primary-dark, #3730a3);
    text-decoration: none;
}

.lux-inv-emp-modal__row-copy a:hover {
    text-decoration: underline;
}

.lux-inv-emp-modal__row-index {
    font-size: 0.6875rem;
    font-weight: 800;
    color: #94a3b8;
}

.lux-inv-emp-modal__empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.35rem;
    padding: 2rem 1rem;
    text-align: center;
    color: #94a3b8;
    font-size: 0.6875rem;
    font-weight: 700;
}

.lux-inv-emp-modal__empty i {
    font-size: 1.25rem;
}

.lux-inv-emp-modal__footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.55rem;
    padding: 0.75rem 1rem;
    border-top: 1px solid rgba(226, 232, 240, 0.95);
    background: rgba(248, 250, 252, 0.96);
}

.lux-inv-emp-modal__footer span {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    font-size: 0.6875rem;
    font-weight: 700;
    color: #64748b;
}

.lux-inv-emp-modal__done-btn {
    min-height: 2rem;
    padding: 0 0.85rem;
    border: none;
    border-radius: 9911px;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    font-size: 0.6875rem;
    font-weight: 800;
    color: #fff;
    cursor: pointer;
    box-shadow: 0 6px 16px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}

/* Responsive */

@media (max-width: 900px) {
    .lux-inv-detail__brand-contacts {
        gap: 0.28rem;
    }

    .lux-inv-detail__hero,
    .lux-inv-detail__settlement,
    .lux-inv-detail__footer {
        grid-template-columns: 1fr;
    }

    .lux-inv-detail__summary-title {
        text-align: left;
    }

    .lux-inv-detail__tax-grid {
        grid-template-columns: 1fr;
    }

    .lux-inv-detail__items-head {
        display: none;
    }

    .lux-inv-detail__item-row {
        grid-template-columns: 1fr;
        gap: 0.35rem;
    }

    .lux-inv-detail__item-row > div:not(:first-child) {
        text-align: left;
    }

    .lux-inv-detail__footer div {
        border-left: none;
        padding-left: 0;
    }
}

@media (max-width: 640px) {
    .lux-inv-detail__toolbar-inner {
        flex-direction: column;
        align-items: stretch;
        padding: 0.65rem 0.85rem;
    }

    .lux-inv-detail__toolbar-actions {
        justify-content: flex-end;
        flex-wrap: wrap;
    }

    .lux-inv-detail__summary-grid {
        grid-template-columns: 1fr;
    }

    .lux-inv-detail__hero,
    .lux-inv-detail__settlement,
    .lux-inv-detail__items {
        padding-left: 1rem;
        padding-right: 1rem;
        margin-left: 0;
        margin-right: 0;
    }

    .lux-inv-detail__brand {
        padding-left: 1rem;
        padding-right: 1rem;
    }

    .lux-inv-detail__terms,
    .lux-inv-detail__footer {
        padding-left: 1rem;
        padding-right: 1rem;
    }

    .lux-inv-emp-modal {
        padding: 0.625rem;
    }

    .lux-inv-emp-modal__footer {
        flex-direction: column;
        align-items: stretch;
    }
}

