}

.lux-planner-btn--ghost {
    background: #fff;
    border-color: rgba(148, 163, 184, 0.35);
    color: #334155;
}

.lux-planner-btn--primary {
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
    color: #fff;
    box-shadow: 0 6px 16px rgba(91, 95, 244, 0.25);
}

.lux-planner-hero {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    margin-bottom: 1.25rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid rgba(148, 163, 184, 0.15);
}

.lux-planner-hero__eyebrow {
    display: block;
    font-size: 0.6875rem;
    text-transform: uppercase;
    letter-spacing: 0.07em;
    color: #64748b;
    font-weight: 600;
}

.lux-planner-hero__title-row {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    flex-wrap: wrap;
}

.lux-planner-hero__title {
    margin: 0;
    font-size: 1.35rem;
    font-weight: 700;
    color: #0f172a;
    letter-spacing: -0.02em;
}

.lux-planner-hero__badge {
    padding: 0.2rem 0.55rem;
    border-radius: 999px;
    font-size: 0.6875rem;
    font-weight: 700;
}

.lux-planner-hero__badge.is-good { background: #d1fae5; color: #047857; }
.lux-planner-hero__badge.is-warn { background: #fef3c7; color: #b45309; }
.lux-planner-hero__badge.is-bad { background: #fee2e2; color: #b91c1c; }

.lux-planner-hero__desc {
    margin: 0.35rem 0 0;
    color: #64748b;
    font-size: 0.875rem;
    max-width: 52rem;
    line-height: 1.5;
}

.lux-planner-hero__meta {
    margin: 0.25rem 0 0;
    font-size: 0.75rem;
    color: #94a3b8;
}

.lux-planner-hero__actions {
    margin-left: auto;
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
    align-items: center;
}

.lux-planner-legend {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem 0.85rem;
    font-size: 0.6875rem;
    color: #64748b;
}

.lux-planner-legend__item {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
}

.lux-planner-legend__swatch {
    width: 14px;
    height: 14px;
    border-radius: 4px;
    border: 2px solid var(--legend-color, #94a3b8);
    background: color-mix(in srgb, var(--legend-color, #94a3b8) 18%, #fff);
}

.lux-planner-legend__swatch.is-available {
    border-color: #10b981;
    background: rgba(16, 185, 129, 0.16);
}

.lux-planner-legend__swatch.is-light {
    border-color: #14b8a6;
    background: rgba(20, 184, 166, 0.12);
}

.lux-planner-legend__swatch.is-balanced {
    border-color: #3b82f6;
    background: rgba(59, 130, 246, 0.12);
}

.lux-planner-legend__swatch.is-high {
    border-color: #f59e0b;
    background: rgba(245, 158, 11, 0.14);
}

.lux-planner-legend__swatch.is-critical {
    border-color: #ef4444;
    background: rgba(239, 68, 68, 0.12);
}

.lux-planner-legend__swatch.is-leave {
    border-color: #a855f7;
    background: rgba(168, 85, 247, 0.12);
}

.lux-planner-panel-head h3 {
    margin: 0;
    font-size: 0.9375rem;
    font-weight: 700;
}

.lux-planner-panel-head p {
    margin: 0.15rem 0 0;
    font-size: 0.75rem;
    color: #64748b;
}

.lux-planner-panel-head {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 0.5rem;
    margin-bottom: 0.65rem;
}

/* Overview */
.lux-planner-overview__top {
    display: grid;
    grid-template-columns: minmax(200px, 260px) 1fr;
    gap: 1rem;
    margin-bottom: 1rem;
}

.lux-planner-health {
    padding: 1rem;
    border-radius: 16px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    background: #fff;
}

.lux-planner-health__ring {
    width: 88px;
    height: 88px;
    border-radius: 50%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    margin-bottom: 0.5rem;
    background: conic-gradient(
        var(--lux-primary, #5b5ff4) calc(var(--score) * 1%),
        #e2e8f0 0
    );
    position: relative;
}

.lux-planner-health__ring::after {
    content: "";
    position: absolute;
    inset: 8px;
    border-radius: 50%;
    background: #fff;
}

.lux-planner-health__ring strong,
.lux-planner-health__ring span {
    position: relative;
    z-index: 1;
    line-height: 1.1;
}

.lux-planner-health__ring strong {
    font-size: 1.25rem;
    color: #0f172a;
}

.lux-planner-health__ring span {
    font-size: 0.625rem;
    color: #64748b;
    text-transform: uppercase;
}

.lux-planner-health p {
    margin: 0;
    font-size: 0.75rem;
    color: #64748b;
    line-height: 1.45;
}

.lux-planner-alert-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 0.5rem;
}

.lux-planner-alert-card {
    display: flex;
    gap: 0.5rem;
    padding: 0.6rem 0.7rem;
    border-radius: 12px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    background: #fff;
    font-size: 0.75rem;
}

.lux-planner-alert-card strong {
    display: block;
    color: #0f172a;
}

.lux-planner-alert-card span {
    color: #64748b;
}

.lux-planner-alert-card.is-critical { border-left: 3px solid #ef4444; }
.lux-planner-alert-card.is-warning { border-left: 3px solid #f59e0b; }
.lux-planner-alert-card.is-info { border-left: 3px solid #3b82f6; }

.lux-planner-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: 0.6rem;
    margin-bottom: 1rem;
}

.lux-planner-kpi-card {
    padding: 0.75rem;
    border-radius: 14px;
    background: #fff;
    border: 1px solid rgba(148, 163, 184, 0.18);
    box-shadow: 0 4px 14px rgba(15, 23, 42, 0.04);
}

.lux-planner-kpi-card__icon {
    width: 28px;
    height: 28px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(91, 95, 244, 0.1);
    color: var(--lux-primary, #5b5ff4);
    margin-bottom: 0.35rem;
}

.lux-planner-kpi-card.is-critical .lux-planner-kpi-card__icon {
    background: rgba(239, 68, 68, 0.12);
    color: #ef4444;
}

.lux-planner-kpi-card__label {
    display: block;
    font-size: 0.6875rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: #64748b;
}

.lux-planner-kpi-card__value {
    font-size: 1.35rem;
    color: #0f172a;
}

.lux-planner-kpi-card small {
    display: block;
    font-size: 0.6875rem;
    color: #94a3b8;
}

.lux-planner-heatmap-preview {
    padding: 0.75rem;
    border-radius: 14px;
    border: 1px solid rgba(148, 163, 184, 0.18);
    background: #fff;
}

.lux-planner-heatmap-preview__days,
.lux-planner-heatmap-preview__row {
    display: grid;
    grid-template-columns: 120px minmax(0, 1fr) 48px;
    gap: 0.35rem;
    align-items: center;
}

.lux-planner-heatmap-preview__days {
    margin-bottom: 0.35rem;
}

.lux-planner-heatmap-preview__days-track {
    display: flex;
    gap: 2px;
    min-width: 0;
}

.lux-planner-heatmap-preview__day {
    flex: 1;
    min-width: 4px;
    text-align: center;
    font-size: 0.625rem;
    font-weight: 600;
    line-height: 1.2;
    color: #94a3b8;
}

.lux-planner-heatmap-preview__day.is-weekend {
    color: #cbd5e1;
}

.lux-planner-heatmap-preview__day.is-today {
    color: var(--lux-primary, #5b5ff4);
    font-weight: 800;
}

.lux-planner-heatmap-preview__cells {
    display: flex;
    gap: 2px;
    min-width: 0;
}

.lux-planner-heatmap-preview__cells span {
    flex: 1;
    height: 14px;
    border-radius: 3px;
    min-width: 4px;
}

.lux-planner-heatmap-preview__name {
    font-size: 0.75rem;
    font-weight: 600;
    color: #334155;
}

.lux-planner-heatmap-preview__pct {
    font-size: 0.6875rem;
    font-weight: 700;
    text-align: right;
}

/* Top projects — luxury portfolio panel */
.lux-planner-projects {
    margin-top: 1.25rem;
    border-radius: 20px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    background: linear-gradient(165deg, #fff 0%, #f8fafc 45%, rgba(91, 95, 244, 0.04) 100%);
    box-shadow: 0 16px 40px rgba(15, 23, 42, 0.06);
    overflow: hidden;
}

.lux-planner-projects__head {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: flex-start;
    gap: 1rem;
    padding: 1.1rem 1.25rem;
    border-bottom: 1px solid rgba(148, 163, 184, 0.15);
    background: linear-gradient(135deg, rgba(91, 95, 244, 0.07), rgba(20, 184, 166, 0.05));
}

.lux-planner-projects__eyebrow {
    display: block;
    font-size: 0.6875rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--lux-primary, #5b5ff4);
    margin-bottom: 0.25rem;
}

.lux-planner-projects__head h3 {
    margin: 0;
    font-size: 1.125rem;
    font-weight: 700;
    color: #0f172a;
    letter-spacing: -0.02em;
}

.lux-planner-projects__head p {
    margin: 0.35rem 0 0;
    max-width: 36rem;
    font-size: 0.8125rem;
    color: #64748b;
    line-height: 1.45;
}

.lux-planner-projects__head-stat {
    padding: 0.65rem 0.85rem;
    border-radius: 14px;
    background: #fff;
    border: 1px solid rgba(148, 163, 184, 0.2);
    text-align: right;
    min-width: 120px;
    box-shadow: 0 4px 14px rgba(15, 23, 42, 0.04);
}

.lux-planner-projects__head-stat span {
    display: block;
    font-size: 0.625rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: #94a3b8;
}

.lux-planner-projects__head-stat strong {
    display: block;
    font-size: 1.5rem;
    font-weight: 700;
    color: #0f172a;
    line-height: 1.2;
}

.lux-planner-projects__head-stat small {
    font-size: 0.6875rem;
    color: #64748b;
}

.lux-planner-projects__body {
    display: grid;
    grid-template-columns: minmax(260px, 1fr) minmax(320px, 1.15fr);
    gap: 0;
}

.lux-planner-projects__chart-panel,
.lux-planner-projects__ranked {
    padding: 1rem 1.15rem;
}

.lux-planner-projects__chart-panel {
    border-right: 1px solid rgba(148, 163, 184, 0.12);
    background: rgba(255, 255, 255, 0.65);
}

.lux-planner-projects__chart-label,
.lux-planner-projects__ranked-label {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.6875rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #64748b;
    margin-bottom: 0.65rem;
}

.lux-planner-projects__chart-skeleton {
    height: 220px;
    border-radius: 12px;
    background: linear-gradient(90deg, #f1f5f9 25%, #e2e8f0 50%, #f1f5f9 75%);
    background-size: 200% 100%;
    animation: luxPlannerShimmer 1.2s ease infinite;
}

@keyframes luxPlannerShimmer {
    0% { background-position: 100% 0; }
    100% { background-position: -100% 0; }
}

.lux-planner-projects__list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.65rem;
}

.lux-planner-projects__row {
    display: grid;
    grid-template-columns: 40px 1fr auto;
    gap: 0.65rem;
    align-items: start;
    padding: 0.75rem 0.85rem;
    border-radius: 14px;
    background: #fff;
    border: 1px solid rgba(148, 163, 184, 0.16);
    transition: box-shadow 0.15s, border-color 0.15s;
}

.lux-planner-projects__row:hover {
    border-color: rgba(91, 95, 244, 0.35);
    box-shadow: 0 10px 24px rgba(91, 95, 244, 0.1);
}

.lux-planner-projects__rank {
    width: 36px;
    height: 36px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #64748b;
    background: #f1f5f9;
}

.lux-planner-projects__rank.is-gold {
    background: linear-gradient(135deg, #fef3c7, #fde68a);
    color: #b45309;
}

.lux-planner-projects__rank.is-silver {
    background: linear-gradient(135deg, #f1f5f9, #e2e8f0);
    color: #475569;
}

.lux-planner-projects__rank.is-bronze {
    background: linear-gradient(135deg, #ffedd5, #fed7aa);
    color: #c2410c;
}

.lux-planner-projects__row-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
    margin-bottom: 0.35rem;
}

.lux-planner-projects__row-top strong {
    font-size: 0.875rem;
    color: #0f172a;
}

.lux-planner-projects__share {
    flex-shrink: 0;
    font-size: 0.75rem;
    font-weight: 800;
    color: var(--lux-primary, #5b5ff4);
    padding: 0.1rem 0.45rem;
    border-radius: 999px;
    background: rgba(91, 95, 244, 0.1);
}

.lux-planner-projects__bar-track {
    height: 6px;
    border-radius: 6px;
    background: rgba(226, 232, 240, 0.9);
    overflow: hidden;
    margin-bottom: 0.45rem;
}

.lux-planner-projects__bar-fill {
    height: 100%;
    border-radius: 6px;
    background: linear-gradient(90deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
    transition: width 0.4s ease;
}

.lux-planner-projects__meta {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem 0.85rem;
    font-size: 0.6875rem;
    color: #64748b;
}

.lux-planner-projects__meta span {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
}

.lux-planner-projects__meta .fe {
    font-size: 0.75rem;
    color: #94a3b8;
}

.lux-planner-projects__statuses {
    display: flex;
    flex-wrap: wrap;
    gap: 0.3rem;
    margin-top: 0.4rem;
}

.lux-planner-projects__status-chip {
    font-size: 0.625rem;
    font-weight: 600;
    padding: 0.12rem 0.4rem;
    border-radius: 6px;
    border-left: 3px solid #94a3b8;
    background: #f8fafc;
    color: #475569;
    text-transform: capitalize;
}

.lux-planner-projects__open {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.5rem 0.6rem;
    border-radius: 12px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    background: linear-gradient(145deg, #fff, #f8fafc);
    color: inherit;
    text-decoration: none;
    min-width: 148px;
    transition: transform 0.12s, box-shadow 0.12s, border-color 0.12s;
}

.lux-planner-projects__open:hover {
    text-decoration: none;
    border-color: rgba(91, 95, 244, 0.4);
    box-shadow: 0 6px 16px rgba(91, 95, 244, 0.15);
    transform: translateY(-1px);
}

.lux-planner-projects__open > .fe:first-child {
    width: 32px;
    height: 32px;
    border-radius: 9px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, rgba(91, 95, 244, 0.15), rgba(20, 184, 166, 0.12));
    color: var(--lux-primary, #5b5ff4);
    font-size: 0.95rem;
}

.lux-planner-projects__open span {
    flex: 1;
    min-width: 0;
}

.lux-planner-projects__open strong {
    display: block;
    font-size: 0.75rem;
    color: #0f172a;
}

.lux-planner-projects__open small {
    display: block;
    font-size: 0.625rem;
    color: #94a3b8;
}

.lux-planner-projects__open .fe-chevron-right {
    color: #94a3b8;
    font-size: 0.875rem;
}

.lux-planner-projects__open.is-muted {
    opacity: 0.85;
    cursor: default;
}

.lux-planner-projects__foot {
    margin-top: 0.75rem;
    padding-top: 0.65rem;
    border-top: 1px dashed rgba(148, 163, 184, 0.25);
}

.lux-planner-projects__report-link {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.8125rem;
    font-weight: 600;
    color: var(--lux-primary, #5b5ff4);
}

.lux-planner-projects--empty {
    padding: 1.25rem;
    text-align: center;
}

@media (max-width: 960px) {
    .lux-planner-projects__body {
        grid-template-columns: 1fr;
    }
    .lux-planner-projects__chart-panel {
        border-right: none;
        border-bottom: 1px solid rgba(148, 163, 184, 0.12);
    }
    .lux-planner-projects__row {
        grid-template-columns: 36px 1fr;
    }
    .lux-planner-projects__row-actions {
        grid-column: 1 / -1;
    }
    .lux-planner-projects__open {
        width: 100%;
    }
}

.lux-planner-chart-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.75rem;
}

.lux-planner-chart-card {
    padding: 0.85rem;
    border-radius: 14px;
    border: 1px solid rgba(148, 163, 184, 0.18);
    background: #fff;
}

.lux-planner-chart-card--wide { grid-column: 1 / -1; }

.lux-planner-attention__chip {
    border-radius: 999px;
    border: 1px solid rgba(148, 163, 184, 0.35);
    background: #fff;
    padding: 0.3rem 0.7rem;
    font-size: 0.75rem;
    margin: 0 0.35rem 0.35rem 0;
}

.lux-planner-attention__chip.is-active {
    border-color: var(--lux-primary, #5b5ff4);
    background: rgba(91, 95, 244, 0.08);
    color: var(--lux-primary, #5b5ff4);
}

/* Roster heatmap */
.lux-planner-roster__controls {
    display: flex;
    flex-wrap: wrap;
    gap: 0.75rem;
    align-items: center;
    margin-bottom: 1rem;
}

.lux-planner-roster__search {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.4rem 0.65rem;
    border-radius: 10px;
    border: 1px solid rgba(148, 163, 184, 0.3);
    background: #fff;
    min-width: 200px;
}

.lux-planner-roster__search input {
    border: none;
    outline: none;
    font-size: 0.8125rem;
    width: 160px;
}

.lux-planner-heatmap-wrap {
    overflow: auto;
    border-radius: 16px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    background: #fff;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

.lux-planner-heatmap {
    min-width: 720px;
}

.lux-planner-heatmap__head-days {
    display: grid;
    gap: 3px;
    padding: 3px 4px 0;
    position: sticky;
    top: 0;
    z-index: 2;
    background: #f8fafc;
    border-bottom: 1px solid rgba(148, 163, 184, 0.2);
}

.lux-planner-heatmap__head-corner {
    padding: 0.35rem 0.5rem;
    font-size: 0.6875rem;
    font-weight: 700;
    color: #64748b;
    display: flex;
    align-items: flex-end;
}

.lux-planner-heatmap__head-day {
    text-align: center;
    padding: 0.35rem 0.15rem;
    font-size: 0.625rem;
    color: #64748b;
    border-radius: 6px;
}

.lux-planner-heatmap__head-day strong {
    display: block;
    font-size: 0.75rem;
    color: #334155;
}

.lux-planner-heatmap__head-day.is-today {
    background: rgba(91, 95, 244, 0.08);
}

.lux-planner-heatmap__head-day.is-holiday {
    background: repeating-linear-gradient(-45deg, rgba(251, 191, 36, 0.15), rgba(251, 191, 36, 0.15) 4px, transparent 4px, transparent 8px);
}

.lux-planner-heatmap__row {
    display: grid;
    gap: 3px;
    padding: 3px 4px;
    border-bottom: 1px solid rgba(241, 245, 249, 0.95);
    align-items: stretch;
}

.lux-planner-heatmap__person {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.45rem 0.5rem;
    border: none;
    background: transparent;
    text-align: left;
    width: 100%;
    cursor: pointer;
}

.lux-planner-heatmap__person:hover {
    background: rgba(91, 95, 244, 0.04);
}

.lux-planner-heatmap__avatar {
    width: 32px;
    height: 32px;
    border-radius: 10px;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
    color: #fff;
    font-weight: 700;
    font-size: 0.8125rem;
    display: flex;
    align-items: center;
    justify-content: center;
}

.lux-planner-heatmap__person-text strong {
    display: block;
    font-size: 0.8125rem;
    color: #0f172a;
}

.lux-planner-heatmap__person-text span {
    font-size: 0.6875rem;
    color: #94a3b8;
}

.lux-planner-util-ring {
    position: relative;
    width: 40px;
    height: 40px;
    margin-left: auto;
    flex-shrink: 0;
}

.lux-planner-util-ring svg {
    width: 100%;
    height: 100%;
    transform: rotate(-90deg);
}

.lux-planner-util-ring__bg {
    fill: none;
    stroke: #e2e8f0;
    stroke-width: 3;
}

.lux-planner-util-ring__fill {
    fill: none;
    stroke: var(--lux-primary, #5b5ff4);
    stroke-width: 3;
    stroke-linecap: round;
}

.lux-planner-util-ring.is-critical .lux-planner-util-ring__fill { stroke: #ef4444; }
.lux-planner-util-ring.is-high .lux-planner-util-ring__fill { stroke: #f59e0b; }
.lux-planner-util-ring.is-available .lux-planner-util-ring__fill { stroke: #10b981; }

.lux-planner-util-ring span {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.5625rem;
    font-weight: 700;
    color: #334155;
}

.lux-planner-heatmap__cell {
    position: relative;
    min-height: 40px;
    margin: 0;
    padding: 0;
    border: 2px solid #e2e8f0;
    border-radius: 6px;
    background: #fff;
    cursor: pointer;
    transition: box-shadow 0.15s ease, transform 0.12s ease;
    overflow: hidden;
}

.lux-planner-heatmap__cell-fill {
    position: absolute;
    left: 0;
    bottom: 0;
    width: 100%;
    height: var(--cell-fill, 0%);
    max-height: 100%;
    background: var(--cell-color, #94a3b8);
    opacity: 0.5;
    pointer-events: none;
    border-radius: 0 0 4px 4px;
}

/* Capacity at a glance — border + tint by utilization band */
.lux-planner-heatmap__cell.is-available {
    border-color: #10b981;
    background: linear-gradient(180deg, rgba(16, 185, 129, 0.18) 0%, rgba(16, 185, 129, 0.06) 100%);
}

.lux-planner-heatmap__cell.is-available.is-empty .lux-planner-heatmap__cell-fill {
    opacity: 0;
}

.lux-planner-heatmap__cell.is-available.is-empty::after {
    content: "";
    position: absolute;
    inset: auto 0 5px 0;
    margin: 0 auto;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #10b981;
    opacity: 0.55;
    pointer-events: none;
}

.lux-planner-heatmap__cell.is-light {
    border-color: #14b8a6;
    background: linear-gradient(180deg, rgba(20, 184, 166, 0.14) 0%, rgba(20, 184, 166, 0.05) 100%);
}

.lux-planner-heatmap__cell.is-balanced {
    border-color: #3b82f6;
    background: linear-gradient(180deg, rgba(59, 130, 246, 0.16) 0%, rgba(59, 130, 246, 0.06) 100%);
}

.lux-planner-heatmap__cell.is-high {
    border-color: #f59e0b;
    background: linear-gradient(180deg, rgba(245, 158, 11, 0.2) 0%, rgba(245, 158, 11, 0.08) 100%);
}

.lux-planner-heatmap__cell.is-high .lux-planner-heatmap__cell-fill {
    opacity: 0.62;
}

.lux-planner-heatmap__cell.is-critical {
    border-color: #ef4444;
    background: linear-gradient(180deg, rgba(239, 68, 68, 0.22) 0%, rgba(239, 68, 68, 0.1) 100%);
}

.lux-planner-heatmap__cell.is-critical .lux-planner-heatmap__cell-fill {
    opacity: 0.68;
}

.lux-planner-heatmap__cell.is-no-capacity:not(.is-on-leave) {
    border-color: #cbd5e1;
    background: #f1f5f9;
    cursor: default;
}

.lux-planner-heatmap__cell.is-no-capacity .lux-planner-heatmap__cell-fill {
    opacity: 0.25;
}

.lux-planner-heatmap__cell.is-weekend:not(.is-on-leave):not(.is-available.is-empty) {
    box-shadow: inset 0 0 0 1px rgba(148, 163, 184, 0.12);
}

.lux-planner-heatmap__cell:hover:not(.is-on-leave):not(.is-no-capacity) {
    box-shadow: 0 2px 10px rgba(15, 23, 42, 0.1);
    transform: translateY(-1px);
    z-index: 1;
}

.lux-planner-heatmap__cell-count {
    position: absolute;
    top: 3px;
    left: 4px;
    z-index: 1;
    font-size: 0.5625rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1;
    padding: 2px 4px;
    border-radius: 4px;
    background: rgba(255, 255, 255, 0.82);
}

.lux-planner-heatmap__cell-free {
    position: absolute;
    right: 3px;
    bottom: 3px;
    z-index: 1;
    font-size: 0.5rem;
    font-weight: 700;
    color: #047857;
    line-height: 1;
    padding: 1px 3px;
    border-radius: 3px;
    background: rgba(255, 255, 255, 0.88);
    pointer-events: none;
}

.lux-planner-heatmap__cell.is-high .lux-planner-heatmap__cell-free,
.lux-planner-heatmap__cell.is-critical .lux-planner-heatmap__cell-free {
    display: none;
}

.lux-planner-heatmap__cell.is-holiday:not(.is-on-leave) {
    background-image: repeating-linear-gradient(
        -45deg,
        rgba(251, 191, 36, 0.1),
        rgba(251, 191, 36, 0.1) 4px,
        transparent 4px,
        transparent 8px
    );
    background-color: #fff;
    background-blend-mode: multiply;
}

.lux-planner-roster__tips {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 0.6rem;
    margin-top: 1rem;
}

.lux-planner-roster__tips article {
    display: flex;
    gap: 0.6rem;
    padding: 0.65rem 0.75rem;
    border-radius: 12px;
    background: rgba(248, 250, 252, 0.95);
    border: 1px solid rgba(148, 163, 184, 0.15);
    font-size: 0.75rem;
}

.lux-planner-roster__tips i {
    color: var(--lux-primary, #5b5ff4);
    font-size: 1.1rem;
}

/* Timeline */
.lux-planner-timeline__capacity-strip {
    display: flex;
    align-items: flex-end;
    gap: 0.65rem;
    margin-bottom: 1rem;
    padding: 0.65rem 0.75rem;
    border-radius: 12px;
    background: #fff;
    border: 1px solid rgba(148, 163, 184, 0.18);
}

.lux-planner-timeline__strip-label {
    font-size: 0.6875rem;
    font-weight: 600;
    color: #64748b;
    writing-mode: vertical-rl;
    transform: rotate(180deg);
}

.lux-planner-timeline__strip-cells {
    display: flex;
    flex: 1;
    gap: 3px;
    height: 48px;
    align-items: flex-end;
}

.lux-planner-timeline__strip-cell {
    flex: 1;
    height: 100%;
    background: #f1f5f9;
    border-radius: 4px 4px 0 0;
    display: flex;
    align-items: flex-end;
}

.lux-planner-timeline__strip-cell span {
    display: block;
    width: 100%;
    border-radius: 4px 4px 0 0;
    background: #94a3b8;
}

.lux-planner-timeline__strip-cell.is-available span { background: #10b981; }
.lux-planner-timeline__strip-cell.is-balanced span { background: #3b82f6; }
.lux-planner-timeline__strip-cell.is-high span { background: #f59e0b; }
.lux-planner-timeline__strip-cell.is-critical span { background: #ef4444; }

.lux-planner-timeline__lane-search {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.75rem;
}

.lux-planner-timeline__lane-search input {
    flex: 1;
    max-width: 280px;
    padding: 0.4rem 0.65rem;
    border-radius: 10px;
    border: 1px solid rgba(148, 163, 184, 0.3);
    font-size: 0.8125rem;
}

.lux-planner-timeline__board {
    border-radius: 16px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    background: #fff;
    overflow: hidden;
}

.lux-planner-timeline__axis {
    display: flex;
    position: relative;
    border-bottom: 1px solid rgba(148, 163, 184, 0.15);
    background: #f8fafc;
    padding-left: 200px;
}

.lux-planner-timeline__axis-day {
    flex: 1;
    text-align: center;
    padding: 0.35rem 0;
    font-size: 0.625rem;
    color: #64748b;
    min-width: 32px;
}

.lux-planner-timeline__axis-day.is-today {
    background: rgba(91, 95, 244, 0.1);
    color: var(--lux-primary, #5b5ff4);
}

.lux-planner-timeline__today {
    position: absolute;
    top: 0;
    bottom: 0;
    width: 2px;
    background: var(--lux-primary, #5b5ff4);
    z-index: 2;
    pointer-events: none;
}

.lux-planner-timeline__lane {
    display: grid;
    grid-template-columns: 200px 1fr;
    border-bottom: 1px solid rgba(241, 245, 249, 0.95);
    min-height: 44px;
}

.lux-planner-timeline__lane-head {
    padding: 0.45rem 0.6rem;
    border-right: 1px solid rgba(241, 245, 249, 0.95);
}

.lux-planner-timeline__lane-head strong {
    display: block;
    font-size: 0.8125rem;
}

.lux-planner-timeline__lane-head span {
    font-size: 0.6875rem;
    color: #94a3b8;
}

.lux-planner-timeline__lane-head em {
    display: block;
    font-size: 0.6875rem;
    font-style: normal;
    color: var(--lux-primary, #5b5ff4);
    font-weight: 600;
}

.lux-planner-timeline__lane-track {
    position: relative;
    min-height: 44px;
    margin: 4px 8px;
}

.lux-planner-timeline__day-grid {
    position: absolute;
    inset: 0;
    display: grid;
    grid-template-columns: repeat(var(--timeline-days, 14), minmax(0, 1fr));
    pointer-events: none;
    z-index: 0;
}

.lux-planner-timeline__day-cell {
    border-right: 1px solid rgba(241, 245, 249, 0.95);
}

.lux-planner-timeline__day-cell.is-weekend {
    background: rgba(248, 250, 252, 0.85);
}

.lux-planner-timeline__day-cell.is-today {
    background: rgba(91, 95, 244, 0.06);
}

.lux-planner-timeline__segments-layer {
    position: relative;
    z-index: 1;
    min-height: 44px;
}

.lux-planner-timeline__segment {
    position: absolute;
    top: 8px;
    height: 30px;
    border: none;
    border-radius: 8px;
    color: #fff;
    font-size: 0.6875rem;
    font-weight: 600;
    padding: 0;
    box-shadow: 0 4px 10px rgba(15, 23, 42, 0.18);
    cursor: pointer;
    overflow: hidden;
    display: flex;
    align-items: center;
    box-sizing: border-box;
    min-width: 2.5%;
    transition: box-shadow 0.12s, transform 0.12s;
}

.lux-planner-timeline__segment:hover,
.lux-planner-timeline__segment:focus-visible {
    z-index: 3;
    box-shadow: 0 6px 16px rgba(15, 23, 42, 0.28);
    transform: translateY(-1px);
    outline: none;
}

.lux-planner-timeline__segment.is-selected {
    outline: 2px solid #fff;
    outline-offset: 1px;
    box-shadow: 0 0 0 2px var(--lux-primary, #5b5ff4), 0 8px 18px rgba(91, 95, 244, 0.35);
    z-index: 4;
}

.lux-planner-timeline__segment-label {
    display: block;
    width: 100%;
    padding: 0 0.5rem;
    line-height: 30px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    text-align: left;
    text-shadow: 0 1px 2px rgba(15, 23, 42, 0.35);
}

.lux-planner-timeline-popover {
    border-radius: 14px;
    background: #fff;
    box-shadow: 0 16px 40px rgba(15, 23, 42, 0.18);
    border: 1px solid rgba(148, 163, 184, 0.2);
    overflow: hidden;
    pointer-events: auto;
}

.lux-planner-timeline-popover__accent {
    height: 4px;
}

.lux-planner-timeline-popover__body {
    padding: 0.65rem 0.75rem 0.75rem;
    font-size: 0.75rem;
}

.lux-planner-timeline-popover__body strong {
    display: block;
    font-size: 0.875rem;
    color: #0f172a;
    margin: 0.25rem 0 0.15rem;
}

.lux-planner-timeline-popover__body p {
    margin: 0 0 0.5rem;
    color: #64748b;
    font-size: 0.6875rem;
}

.lux-planner-timeline-popover__status {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    font-size: 0.625rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: #64748b;
}

.lux-planner-timeline-popover__body dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.2rem 0.5rem;
    margin: 0;
}

.lux-planner-timeline-popover__body dt {
    color: #94a3b8;
    font-weight: 600;
}

.lux-planner-timeline-popover__body dd {
    margin: 0;
    color: #334155;
}

.lux-planner-timeline-popover__hint {
    display: block;
    margin-top: 0.45rem;
    font-size: 0.625rem;
    color: var(--lux-primary, #5b5ff4);
    font-weight: 600;
}

/* Gantt */
.lux-planner-gantt__legend {
    display: flex;
    flex-wrap: wrap;
    gap: 0.65rem;
    align-items: center;
    margin-bottom: 0.75rem;
    font-size: 0.6875rem;
    color: #64748b;
}

.lux-planner-gantt__legend i {
    display: inline-block;
    width: 10px;
    height: 10px;
    border-radius: 2px;
    margin-right: 0.2rem;
}

.lux-planner-gantt__frame {
    display: grid;
    grid-template-columns: 220px 1fr;
    grid-template-rows: auto 1fr;
    border-radius: 16px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    background: #fff;
    overflow: hidden;
    max-height: 70vh;
}

.lux-planner-gantt__sidebar-head,
.lux-planner-gantt__timeline-head {
    padding: 0.45rem 0.5rem;
    font-size: 0.6875rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #64748b;
    background: #f8fafc;
    border-bottom: 1px solid rgba(148, 163, 184, 0.15);
}

.lux-planner-gantt__timeline-head {
    display: flex;
    overflow: hidden;
}

.lux-planner-gantt__day {
    flex-shrink: 0;
    text-align: center;
    font-size: 0.625rem;
    border-right: 1px solid rgba(241, 245, 249, 0.95);
}

.lux-planner-gantt__day.is-today {
    background: rgba(91, 95, 244, 0.1);
}

.lux-planner-gantt__body {
    display: contents;
}

.lux-planner-gantt__sidebar {
    overflow-y: auto;
    border-right: 1px solid rgba(148, 163, 184, 0.15);
    grid-row: 2;
}

.lux-planner-gantt__sidebar-group-btn {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    width: 100%;
    padding: 0.4rem 0.5rem;
    border: none;
    background: rgba(248, 250, 252, 0.95);
    font-size: 0.75rem;
    font-weight: 600;
    text-align: left;
}

.lux-planner-gantt__sidebar-row {
    padding: 0 0.5rem 0 1.25rem;
    font-size: 0.6875rem;
    color: #475569;
    display: flex;
    align-items: center;
    border-bottom: 1px solid rgba(241, 245, 249, 0.9);
}

.lux-planner-gantt__tracks-scroll {
    overflow: auto;
    grid-row: 2;
}

.lux-planner-gantt__canvas {
    position: relative;
    min-height: 120px;
}

.lux-planner-gantt__grid-cols {
    position: absolute;
    inset: 0;
    display: flex;
    pointer-events: none;
    z-index: 0;
}

.lux-planner-gantt__bars-layer {
    position: relative;
    z-index: 1;
}

.lux-planner-gantt__grid-col {
    flex-shrink: 0;
    border-right: 1px solid rgba(241, 245, 249, 0.95);
    min-height: 100%;
}

.lux-planner-gantt__grid-col.is-weekend {
    background: rgba(248, 250, 252, 0.9);
}

.lux-planner-gantt__today-line {
    position: absolute;
    top: 0;
    bottom: 0;
    width: 2px;
    background: var(--lux-primary, #5b5ff4);
    z-index: 3;
    pointer-events: none;
}

.lux-planner-gantt__track-row {
    position: relative;
    border-bottom: 1px solid rgba(241, 245, 249, 0.9);
}

.lux-planner-gantt__bar {
    position: absolute;
    top: 8px;
    height: 24px;
    border: none;
    border-radius: 8px;
    color: #fff;
    font-size: 0.625rem;
    font-weight: 600;
    padding: 0 0.4rem;
    box-shadow: 0 4px 12px rgba(15, 23, 42, 0.18);
    cursor: pointer;
    z-index: 2;
}

.lux-planner-gantt__bar.is-draggable {
    cursor: grab;
}

/* Drawer */
.lux-planner-drawer {
    position: fixed;
    inset: 0;
    z-index: 1050;
    display: flex;
    justify-content: flex-end;
}

.lux-planner-drawer__backdrop {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.35);
    backdrop-filter: blur(2px);
}

.lux-planner-drawer__panel {
    position: relative;
    width: min(420px, 100vw);
    height: 100%;
    background: #fff;
    box-shadow: -12px 0 40px rgba(15, 23, 42, 0.15);
    display: flex;
    flex-direction: column;
    animation: luxPlannerDrawerIn 0.2s ease;
}

@keyframes luxPlannerDrawerIn {
    from { transform: translateX(100%); }
    to { transform: translateX(0); }
}

.lux-planner-drawer__head {
    display: flex;
    justify-content: space-between;
    padding: 1rem 1.1rem;
    border-bottom: 1px solid rgba(148, 163, 184, 0.15);
}

.lux-planner-drawer__head h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
}

.lux-planner-drawer__head p {
    margin: 0.2rem 0 0;
    font-size: 0.75rem;
    color: #64748b;
}

.lux-planner-drawer__close {
    border: none;
    background: rgba(241, 245, 249, 0.95);
    width: 32px;
    height: 32px;
    border-radius: 8px;
}

.lux-planner-drawer__body {
    flex: 1;
    overflow-y: auto;
    padding: 1rem 1.1rem;
}

.lux-planner-drawer__foot {
    padding: 0.85rem 1.1rem;
    border-top: 1px solid rgba(148, 163, 184, 0.15);
}

.lux-planner-metric-tiles {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 0.4rem;
    margin-bottom: 1rem;
}

.lux-planner-metric-tiles__tile {
    padding: 0.5rem;
    border-radius: 10px;
    background: #f8fafc;
    border: 1px solid rgba(148, 163, 184, 0.15);
    font-size: 0.6875rem;
}

.lux-planner-metric-tiles__tile strong {
    display: block;
    font-size: 0.875rem;
    color: #0f172a;
}

.lux-planner-metric-tiles__tile.is-good strong { color: #059669; }
.lux-planner-metric-tiles__tile.is-critical strong { color: #dc2626; }

.lux-planner-assign-list {
    list-style: none;
    margin: 0;
    padding: 0;
}

.lux-planner-assign-list__item {
    display: flex;
    gap: 0.5rem;
    padding: 0.6rem 0;
    border-bottom: 1px solid rgba(241, 245, 249, 0.95);
}

.lux-planner-assign-list__dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    margin-top: 0.35rem;
    flex-shrink: 0;
}

.lux-planner-assign-list__main {
    flex: 1;
    min-width: 0;
}

.lux-planner-assign-list__main strong {
    display: block;
    font-size: 0.8125rem;
}

.lux-planner-assign-list__main span {
    display: block;
    font-size: 0.6875rem;
    color: #64748b;
}

.lux-planner-assign-list__time {
    color: var(--lux-primary, #5b5ff4) !important;
    font-weight: 600;
}

.lux-planner-assign-list__actions {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

/* Luxury detail panel — portaled overlay (roster, timeline, gantt) */
.lux-planner-detail-portal {
    position: fixed;
    inset: 0;
    z-index: 12080;
    pointer-events: none;
}

.lux-planner-detail-portal__backdrop {
    position: fixed;
    inset: 0;
    border: none;
    padding: 0;
    margin: 0;
    background: rgba(15, 23, 42, 0.42);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    cursor: pointer;
    pointer-events: auto;
}

.lux-planner-lux-panel--overlay {
    position: fixed;
    right: 0;
    width: min(440px, 94vw);
    max-width: 100%;
    display: flex;
    flex-direction: column;
    background: #f8fafc;
    border-left: 1px solid rgba(148, 163, 184, 0.28);
    box-shadow: -16px 0 48px rgba(15, 23, 42, 0.2);
    transform: translateX(100%);
    transition: transform 0.22s ease;
    pointer-events: auto;
    overflow: hidden;
    z-index: 12081;
}

.lux-planner-lux-panel--overlay.is-open {
    transform: translateX(0);
}

.lux-planner-lux-panel__sheet {
    position: relative;
    width: 100%;
    height: 100%;
    background: #f8fafc;
    display: flex;
    flex-direction: column;
    min-height: 0;
}

@keyframes luxPlannerSheetIn {
    from { transform: translateX(100%); opacity: 0.6; }
    to { transform: translateX(0); opacity: 1; }
}

.lux-planner-lux-panel__hero {
    position: relative;
    padding: 1.25rem 1.25rem 1rem;
    color: #fff;
    overflow: hidden;
}

.lux-planner-lux-panel__hero-bg {
    position: absolute;
    inset: 0;
    background: linear-gradient(135deg, #5b5ff4 0%, #14b8a6 55%, #0f172a 120%);
    opacity: 0.95;
}

.lux-planner-lux-panel__hero h2,
.lux-planner-lux-panel__hero p,
.lux-planner-lux-panel__status {
    position: relative;
    z-index: 1;
}

.lux-planner-lux-panel__hero h2 {
    margin: 0.35rem 0 0;
    font-size: 1.2rem;
    font-weight: 700;
}

.lux-planner-lux-panel__hero p {
    margin: 0.25rem 0 0;
    font-size: 0.8125rem;
    opacity: 0.9;
}

.lux-planner-lux-panel__close {
    position: absolute;
    top: 0.75rem;
    right: 0.75rem;
    z-index: 2;
    width: 34px;
    height: 34px;
    border: none;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.2);
    color: #fff;
}

.lux-planner-lux-panel__status {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.2rem 0.55rem;
    border-radius: 999px;
    font-size: 0.6875rem;
    font-weight: 700;
    background: rgba(255, 255, 255, 0.2);
}

.lux-planner-lux-panel__bandwidth {
    position: relative;
    z-index: 1;
    margin-top: 0.5rem;
    padding: 0.45rem 0.55rem;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.15);
    font-size: 0.75rem;
    display: flex;
    gap: 0.35rem;
    align-items: flex-start;
}

.lux-planner-lux-panel__body {
    flex: 1;
    overflow-y: auto;
    padding: 1rem 1.1rem 1.25rem;
}

.lux-planner-lux-panel__body h3 {
    font-size: 0.8125rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #64748b;
    margin: 0 0 0.5rem;
}

.lux-planner-lux-metric {
    padding: 0.55rem;
    border-radius: 12px;
    background: #fff;
    border: 1px solid rgba(148, 163, 184, 0.18);
}

.lux-planner-lux-metric span {
    display: block;
    font-size: 0.625rem;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-planner-lux-metric strong {
    font-size: 1rem;
    color: #0f172a;
}

.lux-planner-lux-metric.is-good strong { color: #059669; }
.lux-planner-lux-metric.is-critical strong { color: #dc2626; }

.lux-planner-lux-panel__metrics {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 0.45rem;
    margin-bottom: 1rem;
}

.lux-planner-lux-card {
    display: flex;
    gap: 0.65rem;
    padding: 0.75rem;
    border-radius: 14px;
    background: #fff;
    border: 1px solid rgba(148, 163, 184, 0.18);
    margin-bottom: 1rem;
}

.lux-planner-lux-card__accent {
    width: 4px;
    border-radius: 4px;
    flex-shrink: 0;
}

.lux-planner-lux-dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.2rem 0.65rem;
    margin: 0.5rem 0 0;
    font-size: 0.75rem;
}

.lux-planner-lux-dl dt {
    color: #94a3b8;
    margin: 0;
}

.lux-planner-lux-dl dd {
    margin: 0;
    color: #334155;
}

.lux-planner-lux-list-item {
    display: flex;
    gap: 0.5rem;
    padding: 0.5rem 0;
    border-bottom: 1px solid rgba(241, 245, 249, 0.95);
    list-style: none;
}

.lux-planner-lux-panel__list ul {
    margin: 0;
    padding: 0;
}

.lux-planner-lux-panel__chart {
    margin-bottom: 1rem;
    padding: 0.65rem;
    border-radius: 14px;
    background: #fff;
    border: 1px solid rgba(148, 163, 184, 0.15);
}

.lux-planner-lux-panel__chart-sub {
    font-size: 0.75rem;
    color: #64748b;
    margin: -0.25rem 0 0.5rem;
}

.lux-planner-lux-panel__foot {
    padding: 0.85rem 1.1rem;
    border-top: 1px solid rgba(148, 163, 184, 0.15);
    background: #fff;
}

.lux-planner-btn--block {
    width: 100%;
    justify-content: center;
}

/* Luxury action buttons */
.lux-planner-lux-actions {
    display: flex;
    flex-direction: column;
    gap: 0.45rem;
}

.lux-planner-lux-btn {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    width: 100%;
    padding: 0.65rem 0.75rem;
    border-radius: 14px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    background: #fff;
    text-align: left;
    transition: transform 0.12s, box-shadow 0.12s;
}

.lux-planner-lux-btn:hover {
    transform: translateY(-1px);
    box-shadow: 0 8px 20px rgba(15, 23, 42, 0.08);
}

.lux-planner-lux-btn--primary {
    border-color: transparent;
    background: linear-gradient(135deg, rgba(91, 95, 244, 0.12), rgba(20, 184, 166, 0.12));
}

.lux-planner-lux-btn--accent {
    border-color: transparent;
    background: linear-gradient(135deg, #5b5ff4, #14b8a6);
    color: #fff;
}

.lux-planner-lux-btn--accent .lux-planner-lux-btn__text strong,
.lux-planner-lux-btn--accent .lux-planner-lux-btn__text small,
.lux-planner-lux-btn--accent .lux-planner-lux-btn__chev {
    color: #fff;
}

.lux-planner-lux-btn__icon {
    width: 36px;
    height: 36px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(91, 95, 244, 0.12);
    color: var(--lux-primary, #5b5ff4);
    flex-shrink: 0;
}

.lux-planner-lux-btn--accent .lux-planner-lux-btn__icon {
    background: rgba(255, 255, 255, 0.2);
    color: #fff;
}

.lux-planner-lux-btn__text {
    flex: 1;
    min-width: 0;
}

.lux-planner-lux-btn__text strong {
    display: block;
    font-size: 0.8125rem;
    color: #0f172a;
}

.lux-planner-lux-btn__text small {
    display: block;
    font-size: 0.6875rem;
    color: #64748b;
}

.lux-planner-lux-btn__chev {
    color: #94a3b8;
    font-size: 0.875rem;
}

/* Assign affordance on cells */
.lux-planner-heatmap__cell {
    position: relative;
}

.lux-planner-heatmap__assign,
.lux-planner-hourly__assign {
    position: absolute;
    top: 2px;
    right: 2px;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: linear-gradient(135deg, #5b5ff4, #14b8a6);
    color: #fff;
    display: none;
    align-items: center;
    justify-content: center;
    font-size: 0.625rem;
    z-index: 2;
    box-shadow: 0 4px 10px rgba(91, 95, 244, 0.35);
}

.lux-planner-heatmap__cell:hover .lux-planner-heatmap__assign,
.lux-planner-hourly__cell:hover .lux-planner-hourly__assign {
    display: flex;
}

.lux-planner-heatmap__head-day.is-focus {
    outline: 2px solid var(--lux-primary, #5b5ff4);
    outline-offset: -2px;
}

.lux-planner-heatmap__cell.is-focus {
    outline: 2px solid var(--lux-primary, #5b5ff4);
}

/* Hourly grid */
.lux-planner-hourly-wrap {
    border-radius: 16px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    background: #fff;
    overflow: auto;
}

.lux-planner-hourly__head,
.lux-planner-hourly__row {
    display: grid;
    align-items: stretch;
}

.lux-planner-hourly__head {
    position: sticky;
    top: 0;
    z-index: 2;
    background: #f8fafc;
    border-bottom: 1px solid rgba(148, 163, 184, 0.2);
    font-size: 0.625rem;
    font-weight: 700;
    color: #64748b;
    text-align: center;
}

.lux-planner-hourly__head span:first-child {
    text-align: left;
    padding: 0.4rem 0.5rem;
}

.lux-planner-hourly__person {
    padding: 0.4rem 0.5rem;
    border: none;
    background: transparent;
    text-align: left;
    font-size: 0.75rem;
    font-weight: 600;
}

.lux-planner-hourly__cell {
    position: relative;
    min-height: 40px;
    border: none;
    border-right: 1px solid rgba(241, 245, 249, 0.95);
    background: #fafafa;
    cursor: pointer;
}

.lux-planner-hourly__cell.has-bandwidth {
    background: rgba(16, 185, 129, 0.06);
}

.lux-planner-hourly__fill {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    background: #5b5ff4;
    opacity: 0.35;
    pointer-events: none;
}

.lux-planner-hourly__cell em {
    position: relative;
    z-index: 1;
    font-size: 0.625rem;
    font-style: normal;
    font-weight: 700;
}

.lux-planner-roster__date-pick {
    padding: 0.35rem 0.5rem;
    border-radius: 8px;
    border: 1px solid rgba(148, 163, 184, 0.3);
    font-size: 0.8125rem;
}

/* Fluid Gantt */
.lux-planner-gantt--fluid {
    width: 100%;
}

.lux-planner-gantt__frame--fluid {
    display: grid;
    grid-template-columns: 220px 1fr;
    grid-template-rows: auto 1fr;
    width: 100%;
    max-height: min(72vh, 720px);
    border-radius: 16px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    overflow: hidden;
}

.lux-planner-gantt__timeline-head--fluid {
    grid-column: 2;
    overflow: hidden;
    border-bottom: 1px solid rgba(148, 163, 184, 0.15);
}

.lux-planner-gantt__timeline-inner {
    display: flex;
    min-width: 100%;
}

.lux-planner-gantt__day {
    flex-shrink: 0;
    text-align: center;
    padding: 0.35rem 0.15rem;
    font-size: 0.625rem;
    border-right: 1px solid rgba(241, 245, 249, 0.95);
}

.lux-planner-gantt__day strong {
    display: block;
    font-size: 0.6875rem;
}

.lux-planner-gantt__body--fluid {
    display: contents;
}

.lux-planner-gantt__tracks-scroll {
    grid-column: 2;
    overflow: auto;
}

.lux-planner-gantt__grid-cols {
    display: flex;
    position: absolute;
    inset: 0;
    pointer-events: none;
}

.lux-planner-timeline__chart-card {
    margin-bottom: 1rem;
    padding: 0.85rem;
    border-radius: 14px;
    background: #fff;
    border: 1px solid rgba(148, 163, 184, 0.18);
}

.lux-planner-timeline__chart-card h3 {
    margin: 0 0 0.5rem;
    font-size: 0.875rem;
}

.lux-planner-timeline__strip-cell em {
    display: block;
    font-size: 0.5625rem;
    font-style: normal;
    text-align: center;
    margin-top: 2px;
    color: #64748b;
}

.lux-planner-gantt__date-pick {
    padding: 0.35rem 0.5rem;
    border-radius: 10px;
    border: 1px solid rgba(148, 163, 184, 0.35);
    font-size: 0.75rem;
    background: #fff;
}

.lux-planner-gantt__day--hour {
    font-size: 0.625rem;
}

.lux-planner-gantt__day--hour strong {
    display: none;
}

.lux-planner-timeline__board--fluid {
    width: 100%;
}

.lux-planner-shell__view {
    min-height: 200px;
}

.lux-planner-page > .lux-page-header {
    margin: 0;
    border-radius: 0;
    border-left: none;
    border-right: none;
    border-top: none;
}

body.lux-shell-dark .lux-planner-shell__intro {
    border-bottom-color: rgba(51, 65, 85, 0.95);
}

/* Leave, actuals, drag-assign, capacity panel */
.lux-planner-heatmap__cell.is-on-leave {
    border-color: #a855f7;
    background: repeating-linear-gradient(
        -45deg,
        rgba(168, 85, 247, 0.14),
        rgba(168, 85, 247, 0.14) 4px,
        rgba(168, 85, 247, 0.05) 4px,
        rgba(168, 85, 247, 0.05) 8px
    );
    cursor: default;
}

.lux-planner-heatmap__cell.is-on-leave .lux-planner-heatmap__cell-fill {
    opacity: 0.35;
    background: #a855f7;
}

.lux-planner-heatmap__leave-mark {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #7c3aed;
    font-size: 0.75rem;
    z-index: 1;
}

.lux-planner-heatmap__actual-bar {
    position: absolute;
    left: 2px;
    bottom: 2px;
    height: 3px;
    max-width: calc(100% - 4px);
    background: #0ea5e9;
    border-radius: 2px;
    z-index: 1;
    pointer-events: none;
}

.lux-planner-heatmap__cell.is-drop-target,
.lux-planner-hourly__cell.is-drop-target {
    outline: 2px dashed var(--lux-primary, #5b5ff4);
    outline-offset: -2px;
    background: rgba(91, 95, 244, 0.08);
}

.lux-planner-hourly__cell.is-on-leave {
    background: repeating-linear-gradient(
        -45deg,
        rgba(168, 85, 247, 0.1),
        rgba(168, 85, 247, 0.1) 3px,
        transparent 3px,
        transparent 6px
    );
}

.lux-planner-roster__leave-tag {
    display: block;
    font-size: 0.5625rem;
    font-weight: 700;
    color: #7c3aed;
    font-style: normal;
}

.lux-planner-roster__layout {
    display: grid;
    grid-template-columns: 1fr minmax(200px, 260px);
    gap: 0.75rem;
    align-items: start;
}

.lux-planner-roster__grid-pane {
    min-width: 0;
}

.lux-planner-assign-tray {
    border-radius: 14px;
    border: 1px solid rgba(148, 163, 184, 0.25);
    background: #f8fafc;
    position: sticky;
    top: 0.5rem;
    max-height: calc(100vh - 120px);
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

.lux-planner-assign-tray.is-collapsed .lux-planner-assign-tray__list {
    display: none;
}

.lux-planner-assign-tray__head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.5rem 0.65rem;
    border-bottom: 1px solid rgba(148, 163, 184, 0.2);
    font-size: 0.75rem;
}

.lux-planner-assign-tray__head strong {
    display: block;
    color: #0f172a;
}

.lux-planner-assign-tray__toggle {
    border: none;
    background: transparent;
    color: #64748b;
}

.lux-planner-assign-tray__list {
    padding: 0.5rem;
    overflow-y: auto;
    flex: 1;
}

.lux-planner-assign-tray__card {
    display: flex;
    gap: 0.35rem;
    padding: 0.4rem;
    margin-bottom: 0.35rem;
    border-radius: 10px;
    background: #fff;
    border: 1px solid rgba(148, 163, 184, 0.2);
    cursor: grab;
    font-size: 0.6875rem;
}

.lux-planner-assign-tray__card:active {
    cursor: grabbing;
}

.lux-planner-assign-tray__card-body strong {
    display: block;
    color: #0f172a;
}

.lux-planner-assign-tray__card-body span {
    color: #64748b;
}

.lux-planner-assign-tray__card-body em {
    display: block;
    font-style: normal;
    color: #5b5ff4;
    font-weight: 600;
}

.lux-planner-assign-tray__hint,
.lux-planner-assign-tray__empty {
    font-size: 0.625rem;
    color: #64748b;
    margin: 0.25rem 0 0;
}

.lux-planner-conflict {
    position: fixed;
    inset: 0;
    z-index: 12000;
    display: flex;
    align-items: center;
    justify-content: center;
}

.lux-planner-conflict__backdrop {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.45);
}

.lux-planner-conflict__sheet {
    position: relative;
    width: min(420px, 92vw);
    padding: 1.25rem;
    border-radius: 16px;
    background: #fff;
    box-shadow: 0 24px 48px rgba(15, 23, 42, 0.2);
}

.lux-planner-conflict__msg {
    display: flex;
    gap: 0.5rem;
    align-items: flex-start;
    padding: 0.5rem 0.65rem;
    border-radius: 10px;
    font-size: 0.8125rem;
    margin: 0.5rem 0;
}

.lux-planner-conflict__msg.is-error {
    background: rgba(239, 68, 68, 0.08);
    color: #b91c1c;
}

.lux-planner-conflict__msg.is-warn {
    background: rgba(245, 158, 11, 0.1);
    color: #b45309;
}

.lux-planner-conflict__actions {
    display: flex;
    justify-content: flex-end;
    gap: 0.5rem;
    margin-top: 1rem;
}

.lux-planner-capacity-portal {
    position: fixed;
    inset: 0;
    z-index: 12100;
    pointer-events: none;
}

.lux-planner-capacity-portal__backdrop {
    position: fixed;
    inset: 0;
    border: none;
    padding: 0;
    margin: 0;
    background: rgba(15, 23, 42, 0.42);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    cursor: pointer;
    pointer-events: auto;
}

.lux-planner-capacity-panel {
    position: fixed;
    right: 0;
    width: min(400px, 94vw);
    max-width: 100%;
    display: flex;
    flex-direction: column;
    background: #f8fafc;
    border-left: 1px solid rgba(148, 163, 184, 0.28);
    box-shadow: -16px 0 48px rgba(15, 23, 42, 0.18);
    transform: translateX(100%);
    transition: transform 0.22s ease;
    pointer-events: auto;
    overflow: hidden;
    z-index: 12101;
}

.lux-planner-capacity-panel.is-open {
    transform: translateX(0);
}

.lux-planner-capacity-panel__hero {
    position: relative;
    flex-shrink: 0;
    padding: 1rem 1rem 0.85rem;
    color: #fff;
    overflow: hidden;
}

.lux-planner-capacity-panel__hero-bg {
    position: absolute;
    inset: 0;
    background: linear-gradient(135deg, #5b5ff4 0%, #14b8a6 55%, #0f172a 120%);
    opacity: 0.95;
}

.lux-planner-capacity-panel__hero h2,
.lux-planner-capacity-panel__hero p,
.lux-planner-capacity-panel__eyebrow,
.lux-planner-capacity-panel__search {
    position: relative;
    z-index: 1;
}

.lux-planner-capacity-panel__eyebrow {
    display: block;
    font-size: 0.625rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    opacity: 0.9;
    margin-bottom: 0.2rem;
}

.lux-planner-capacity-panel__hero h2 {
    margin: 0;
    font-size: 1.125rem;
    font-weight: 700;
}

.lux-planner-capacity-panel__hero p {
    margin: 0.3rem 0 0.65rem;
    font-size: 0.75rem;
    opacity: 0.92;
    line-height: 1.4;
}

.lux-planner-capacity-panel__close {
    position: absolute;
    top: 0.65rem;
    right: 0.65rem;
    z-index: 2;
    width: 32px;
    height: 32px;
    border: none;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.2);
    color: #fff;
    cursor: pointer;
}

.lux-planner-capacity-panel__search {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.4rem 0.55rem;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.18);
    border: 1px solid rgba(255, 255, 255, 0.25);
}

.lux-planner-capacity-panel__search input {
    flex: 1;
    min-width: 0;
    border: none;
    outline: none;
    background: transparent;
    color: #fff;
    font-size: 0.8125rem;
}

.lux-planner-capacity-panel__search input::placeholder {
    color: rgba(255, 255, 255, 0.75);
}

.lux-planner-capacity-panel__body {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    padding: 0.75rem 0.85rem 1rem;
    -webkit-overflow-scrolling: touch;
}

.lux-planner-capacity-intro {
    display: flex;
    gap: 0.45rem;
    align-items: flex-start;
    padding: 0.55rem 0.65rem;
    margin-bottom: 0.75rem;
    border-radius: 12px;
    background: rgba(91, 95, 244, 0.08);
    color: #475569;
    font-size: 0.75rem;
    line-height: 1.4;
}

.lux-planner-capacity-intro i {
    color: var(--lux-primary, #5b5ff4);
    margin-top: 0.1rem;
}

.lux-planner-capacity-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.lux-planner-capacity-list__empty {
    padding: 1.5rem 1rem;
    text-align: center;
    color: #64748b;
    font-size: 0.8125rem;
}

.lux-planner-capacity-card {
    padding: 0.65rem 0.75rem;
    border-radius: 14px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    background: linear-gradient(160deg, #fff, #f8fafc);
    box-shadow: 0 4px 14px rgba(15, 23, 42, 0.04);
}

.lux-planner-capacity-card.has-override {
    border-color: rgba(91, 95, 244, 0.35);
    box-shadow: 0 6px 18px rgba(91, 95, 244, 0.1);
}

.lux-planner-capacity-card__person {
    display: flex;
    gap: 0.55rem;
    align-items: center;
    margin-bottom: 0.5rem;
}

.lux-planner-capacity-card__avatar {
    width: 36px;
    height: 36px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 0.875rem;
    color: #fff;
    background: linear-gradient(135deg, #5b5ff4, #14b8a6);
    flex-shrink: 0;
}

.lux-planner-capacity-card__person strong {
    display: block;
    font-size: 0.8125rem;
