.lux-fb-create-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.5rem 0.6rem;
}

.lux-fb-create-grid__full {
    grid-column: 1 / -1;
}

.lux-fb-create-grid .form-group {
    margin-bottom: 0 !important;
}

.lux-fb-create-grid .form-control,
.lux-fb-create-grid textarea.form-control {
    border-radius: 12px !important;
    border-color: #e2e8f0 !important;
    font-weight: 600;
}

/* Schedule section — aligned date + toggle rows */
.lux-fb-create-schedule__dates {
    align-items: start;
}

.lux-fb-create-schedule__dates .react-datepicker-wrapper {
    display: block;
    width: 100%;
}

.lux-fb-create-schedule__dates .react-datepicker-wrapper .form-control {
    width: 100%;
    min-height: 2.25rem;
}

.lux-fb-create-schedule__end-date .form-group {
    margin-bottom: 0 !important;
}

.lux-fb-create-schedule__end-date.is-inactive .form-control {
    background: #f8fafc;
}

.lux-fb-create-schedule__end-hint {
    margin: 0.2rem 0 0;
    font-size: 0.5625rem;
    font-weight: 600;
    line-height: 1.3;
    color: #94a3b8;
}

.lux-fb-create-schedule__toggles {
    margin-top: 0.5rem;
    align-items: end;
}

.lux-fb-create-schedule__toggles .form-group {
    margin-bottom: 0 !important;
}

.lux-fb-create-schedule__toggles .custom-controls-stacked {
    margin-top: 0.28rem !important;
    min-height: 2.25rem;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
}

.lux-fb-create-recurring {
    margin-top: 0.55rem;
    padding-top: 0.55rem;
    border-top: 1px dashed #e2e8f0;
}

.lux-fb-create-recurring__schedule {
    margin-top: 0.5rem;
}

.lux-fb-create-recurring__schedule-label {
    margin: 0 0 0.35rem;
    font-size: 0.625rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #94a3b8;
}

.lux-fb-create-form .lux-create-footer {
    flex-shrink: 0;
    margin: 0;
    border-top: 1px solid #e2e8f0;
    border-radius: 0;
    background: #f8fafc;
}

/* Recipients panel */
.lux-fb-recipients {
    display: flex;
    flex-direction: column;
    height: 100%;
    min-height: 320px;
    border: 1px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.2);
    border-radius: 14px;
    background: linear-gradient(180deg, #fff 0%, rgba(248, 250, 252, 0.95) 100%);
    box-shadow: 0 8px 22px rgba(15, 23, 42, 0.05);
    overflow: hidden;
}

.lux-fb-recipients.is-empty .lux-fb-recipients__list-wrap.has-error {
    border-color: #fca5a5;
    background: #fffafb;
}

.lux-fb-recipients__head {
    display: flex;
    align-items: flex-start;
    gap: 0.5rem;
    padding: 0.6rem 0.7rem;
    border-bottom: 1px solid #e2e8f0;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05);
}

.lux-fb-recipients__head-icon {
    width: 1.85rem;
    height: 1.85rem;
    display: grid;
    place-items: center;
    border-radius: 10px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    color: var(--lux-primary, #5b5ff4);
    flex-shrink: 0;
}

.lux-fb-recipients__head h4 {
    margin: 0;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-fb-recipients__head p {
    margin: 0.08rem 0 0;
    font-size: 0.625rem;
    color: #64748b;
    line-height: 1.35;
}

.lux-fb-recipients__count {
    margin-left: auto;
    min-width: 1.5rem;
    height: 1.5rem;
    display: grid;
    place-items: center;
    padding: 0 0.35rem;
    border-radius: 999px;
    font-size: 0.6875rem;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-fb-recipients__body {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
    margin: 0.5rem 0.6rem 0;
    overflow: hidden;
}

.lux-fb-recipients__list-wrap {
    flex: 1;
    min-height: 0;
    border: 1px solid #e2e8f0;
    border-radius: 12px;
    overflow: auto;
    background: #fff;
}

.lux-fb-recipients__footer {
    flex-shrink: 0;
    padding: 0.5rem 0.6rem 0.6rem;
    border-top: 1px solid #e2e8f0;
    background: rgba(248, 250, 252, 0.95);
}

.lux-fb-recipients__list-wrap.has-error {
    border-color: #f87171;
}

/* Recipients empty — rich illustration */
.lux-fb-recipients__list-wrap .lux-fb-recipients-empty {
    height: 100%;
    min-height: 100%;
}

.lux-fb-recipients-empty {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    min-height: min-content;
    padding: 0.75rem 0.65rem 0.85rem;
    text-align: center;
}

.lux-fb-recipients-empty__glow {
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background: linear-gradient(105deg, transparent 40%, rgba(255, 255, 255, 0.55) 50%, transparent 60%);
    pointer-events: none;
    opacity: 0.5;
}

.lux-fb-recipients-empty__art {
    position: relative;
    width: 100%;
    max-width: 8.5rem;
    margin: 0 auto 0.45rem;
}

.lux-fb-recipients-empty__art svg {
    display: block;
    width: 100%;
    height: auto;
    filter: drop-shadow(0 10px 22px rgba(15, 23, 42, 0.08));
}

.lux-fb-recipients-empty__copy {
    position: relative;
    width: 100%;
    min-width: 0;
}

.lux-fb-recipients-empty__eyebrow {
    display: inline-flex;
    align-items: center;
    margin-bottom: 0.35rem;
    padding: 0.15rem 0.5rem;
    border-radius: 999px;
    border: 1px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    font-size: 0.5625rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--lux-primary-dark, #3730a3);
}

.lux-fb-recipients-empty__title {
    margin: 0 0 0.3rem;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.02em;
    line-height: 1.25;
}

.lux-fb-recipients-empty__text {
    margin: 0;
    font-size: 0.625rem;
    line-height: 1.45;
    color: #64748b;
}

.lux-fb-recipients-empty__hints {
    list-style: none;
    margin: 0.5rem 0 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.28rem;
    text-align: left;
}

.lux-fb-recipients-empty__hints li {
    display: flex;
    align-items: flex-start;
    gap: 0.28rem;
    font-size: 0.5625rem;
    line-height: 1.35;
    color: #64748b;
    font-weight: 600;
}

.lux-fb-recipients-empty__hints li .fe {
    flex-shrink: 0;
    margin-top: 0.05rem;
    font-size: 0.6875rem;
    color: #10b981;
}

.lux-fb-recipients-empty__cta {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.3rem;
    margin-top: 0.55rem;
    min-height: 2rem;
    padding: 0 0.85rem;
    border: none;
    border-radius: 999px;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    color: #fff;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    cursor: pointer;
    box-shadow: 0 6px 18px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    transition: transform 0.14s ease, box-shadow 0.14s ease;
}

.lux-fb-recipients-empty__cta:hover {
    transform: translateY(-1px);
    box-shadow: 0 10px 22px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.34);
}

.lux-fb-recipients.is-empty .lux-fb-recipients__list-wrap.has-error .lux-fb-recipients-empty__eyebrow {
    border-color: rgba(248, 113, 113, 0.35);
    background: rgba(254, 226, 226, 0.5);
    color: #b91c1c;
}

.lux-fb-recipients__list {
    margin: 0;
    padding: 0.25rem;
    list-style: none;
}

.lux-fb-recipients__row {
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    gap: 0.4rem;
    padding: 0.4rem 0.45rem;
    border-radius: 10px;
}

.lux-fb-recipients__row:hover {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05);
}

.lux-fb-recipients__index {
    width: 1.25rem;
    font-size: 0.625rem;
    font-weight: 800;
    color: #94a3b8;
    text-align: center;
}

.lux-fb-recipients__identity {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 0.05rem;
}

.lux-fb-recipients__identity strong {
    font-size: 0.75rem;
    color: #0f172a;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-fb-recipients__identity span {
    font-size: 0.6875rem;
    color: #64748b;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-fb-recipients__remove {
    display: grid;
    place-items: center;
    width: 1.65rem;
    height: 1.65rem;
    padding: 0;
    border: 1px solid #fecaca;
    border-radius: 8px;
    background: #fff;
    color: #dc2626;
    cursor: pointer;
}

.lux-fb-recipients__remove:hover {
    background: #fef2f2;
}

.lux-fb-recipients__footer .lux-fb-recipients__add-trigger {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.35rem;
    width: 100%;
    min-height: 2.15rem;
    margin: 0;
    padding: 0 0.85rem;
    border: none;
    border-radius: 999px;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #fff;
    cursor: pointer;
    box-shadow: 0 6px 18px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    transition: transform 0.14s ease, box-shadow 0.14s ease;
}

.lux-fb-recipients__footer .lux-fb-recipients__add-trigger:hover {
    transform: translateY(-1px);
    box-shadow: 0 10px 22px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.34);
}

.lux-fb-recipients__add-panel {
    flex-shrink: 0;
    margin: 0 0.6rem 0.65rem;
    padding: 0.55rem 0.6rem;
    border: 1px solid #e2e8f0;
    border-radius: 12px;
    background: #fff;
}

.lux-fb-recipients__add-title {
    margin: 0 0 0.4rem;
    font-size: 0.625rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: #94a3b8;
}

.lux-fb-recipients__add-fields {
    display: grid;
    grid-template-columns: 1fr;
    gap: 0.4rem;
}

.lux-fb-recipients__add-fields .form-group {
    margin-bottom: 0 !important;
}

.lux-fb-recipients__add-actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-end;
    gap: 0.4rem;
    margin-top: 0.5rem;
    padding-top: 0.45rem;
    border-top: 1px solid #f1f5f9;
}

.lux-fb-recipients__btn {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    padding: 0.38rem 0.7rem;
    border-radius: 10px;
    border: 1px solid #e2e8f0;
    font-size: 0.6875rem;
    font-weight: 800;
    cursor: pointer;
    white-space: nowrap;
}

.lux-fb-recipients__btn.is-primary {
    color: #fff;
    border-color: transparent;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
}

.lux-fb-recipients__btn.is-primary:disabled {
    opacity: 0.45;
    cursor: not-allowed;
}

.lux-fb-recipients__btn.is-ghost {
    color: #64748b;
    background: #f8fafc;
}

.lux-fb-recipients__btn.is-ghost:hover {
    color: #0f172a;
    border-color: #cbd5e1;
}

@media (max-width: 960px) {
    .lux-fb-create-form__layout {
        grid-template-columns: 1fr;
    }

    .lux-fb-create-form__aside {
        position: static;
    }

    .lux-fb-create-schedule__dates,
    .lux-fb-create-schedule__toggles {
        grid-template-columns: 1fr;
    }
}

.lux-feedback-recurring-panel {
    margin-top: 0.5rem;
    padding: 0.65rem 0.75rem;
    border-radius: 12px;
    border: 1px solid rgba(148, 163, 184, 0.25);
    background: rgba(248, 250, 252, 0.9);
}

.lux-feedback-config-cron {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.4rem;
}

.lux-feedback-config-cron__label {
    font-size: 0.6875rem;
    font-weight: 700;
    color: #64748b;
    margin: 0;
}

.lux-feedback-config-cron__value {
    font-size: 0.8125rem;
    font-weight: 700;
    color: #0f172a;
    cursor: pointer;
}

.lux-feedback-config-cron__btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.75rem;
    height: 1.75rem;
    border: 1px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.3);
    border-radius: 8px;
    background: #fff;
    color: var(--lux-primary, #5b5ff4);
    cursor: pointer;
}

.lux-feedback-email-table {
    border-radius: 12px;
    border: 1px solid rgba(148, 163, 184, 0.28);
    overflow: hidden;
}

.lux-feedback-email-table table {
    margin: 0;
    font-size: 0.75rem;
}

.lux-feedback-email-table thead th {
    padding: 0.4rem 0.55rem;
    background: #f1f5f9;
    font-size: 0.625rem;
    font-weight: 800;
    text-transform: uppercase;
    color: #64748b;
}

.lux-feedback-email-table tbody td {
    padding: 0.35rem 0.55rem;
    border-top: 1px solid rgba(226, 232, 240, 0.9);
}

.lux-feedback-email-add__link {
    border: none;
    background: none;
    padding: 0.35rem 0 0;
    font-size: 0.6875rem;
    font-weight: 800;
    color: var(--lux-primary, #5b5ff4);
    cursor: pointer;
}

/* Campaign list */
.lux-feedback-list-section {
    padding: 0 0.65rem 1rem;
}

.lux-feedback-pagination {
    margin: 0 0.65rem 1.25rem;
    padding-top: 0.35rem;
}

.lux-feedback-list {
    display: flex;
    flex-direction: column;
    gap: 0.55rem;
}

.lux-feedback-recurring-label {
    margin: 0.75rem 0 0.35rem;
    padding: 0.35rem 0.65rem;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
    border-radius: 8px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

/* Project / item groups */
.lux-feedback-group {
    margin-bottom: 0.65rem;
    border-radius: 16px;
    border: 1px solid rgba(148, 163, 184, 0.28);
    background: #fff;
    box-shadow: 0 10px 26px rgba(15, 23, 42, 0.06);
    overflow: hidden;
}

.lux-feedback-group__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.65rem;
    padding: 0.55rem 0.85rem;
    cursor: pointer;
    background: linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06), rgba(255, 255, 255, 0.98));
    border-bottom: 1px solid rgba(148, 163, 184, 0.18);
}

.lux-feedback-group__header:hover {
    background: linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1), rgba(255, 255, 255, 0.98));
}

.lux-feedback-group__toggle {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    min-width: 0;
    flex: 1;
    border: none;
    background: none;
    padding: 0;
    text-align: left;
    cursor: pointer;
    color: inherit;
}

.lux-feedback-group__id {
    font-size: 0.6875rem;
    font-weight: 800;
    color: var(--lux-primary, #5b5ff4);
}

.lux-feedback-group__name {
    font-size: 0.875rem;
    font-weight: 700;
    color: #0f172a;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.lux-feedback-group__open {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 9px;
    border: 1px solid rgba(148, 163, 184, 0.35);
    color: #475569;
    flex-shrink: 0;
}

.lux-feedback-group__open:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
    color: var(--lux-primary, #5b5ff4);
}

.lux-feedback-group__body {
    padding: 0.55rem 0.65rem 0.65rem;
}

/* Campaign card */
.lux-feedback-card {
    border-radius: 14px;
    border: 1px solid rgba(148, 163, 184, 0.28);
    background: #fff;
    box-shadow: 0 6px 18px rgba(15, 23, 42, 0.05);
    overflow: hidden;
}

.lux-feedback-card.is-expanded {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    box-shadow: 0 10px 26px rgba(15, 23, 42, 0.08);
}

.lux-feedback-card__bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.65rem;
    padding: 0.55rem 0.75rem;
    cursor: pointer;
}

.lux-feedback-card__main {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    min-width: 0;
    flex: 1;
}

.lux-feedback-card__status-icon {
    flex-shrink: 0;
    font-size: 1rem;
}

.lux-feedback-card__status-icon.is-on { color: #16a34a; }
.lux-feedback-card__status-icon.is-off { color: #dc2626; }
.lux-feedback-card__status-icon.is-warn { color: #d97706; }
.lux-feedback-card__status-icon.is-info { color: #2563eb; }
.lux-feedback-card__status-icon.is-spin { color: #d97706; }

.lux-feedback-card__id {
    font-size: 0.6875rem;
    font-weight: 800;
    color: var(--lux-primary, #5b5ff4);
}

.lux-feedback-card__name {
    font-size: 0.8125rem;
    font-weight: 700;
    color: #0f172a;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.lux-feedback-card__actions {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    flex-shrink: 0;
}

.lux-feedback-card__counts {
    display: inline-flex;
    align-items: center;
    gap: 0.15rem;
    font-size: 0.6875rem;
    font-weight: 700;
}

.lux-feedback-card__count-received {
    padding: 0.12rem 0.4rem;
    border-radius: 999px;
    background: rgba(22, 163, 74, 0.12);
    color: #15803d;
}

.lux-feedback-card__count-pending {
    padding: 0.12rem 0.4rem;
    border-radius: 999px;
    background: rgba(245, 158, 11, 0.15);
    color: #b45309;
}

.lux-feedback-card__date {
    font-size: 0.6875rem;
    font-weight: 600;
    color: #64748b;
    white-space: nowrap;
}

.lux-feedback-card__cron {
    font-size: 0.6875rem;
    color: #94a3b8;
    max-width: 10rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.lux-feedback-card__icon-btn {
    width: 2rem;
    height: 2rem;
    border: 1px solid rgba(148, 163, 184, 0.35);
    border-radius: 9px;
    background: #fff;
    color: #475569;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
}

.lux-feedback-card__icon-btn:hover:not(:disabled) {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
    color: var(--lux-primary, #5b5ff4);
}

.lux-feedback-card__icon-btn:disabled {
    opacity: 0.45;
    cursor: not-allowed;
}

.lux-feedback-card__icon-btn.is-delete:hover {
    color: #dc2626;
    border-color: rgba(220, 38, 38, 0.35);
    background: #fef2f2;
}

.lux-feedback-card__detail {
    padding: 0.65rem 0.85rem 0.75rem;
    border-top: 1px solid rgba(148, 163, 184, 0.18);
    background: linear-gradient(180deg, #f8fafc, #fff);
}

.lux-feedback-detail-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.55rem 0.75rem;
}

.lux-feedback-detail-item label {
    display: block;
    margin: 0 0 0.15rem;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-feedback-detail-item span,
.lux-feedback-detail-item a {
    display: block;
    font-size: 0.75rem;
    font-weight: 600;
    color: #0f172a;
    line-height: 1.4;
}

.lux-feedback-detail-item a {
    color: var(--lux-primary, #5b5ff4);
}

.lux-feedback-recipients {
    grid-column: 1 / -1;
    margin-top: 0.35rem;
    padding: 0.65rem 0.75rem;
    border-radius: 12px;
    border: 1px solid rgba(148, 163, 184, 0.25);
    background: #fff;
}

.lux-feedback-recipients__title {
    margin: 0 0 0.5rem;
    font-size: 0.75rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-feedback-recipients__empty {
    text-align: center;
    padding: 1rem;
    font-size: 0.8125rem;
    color: #64748b;
}

/* Recipient row */
.lux-feedback-recipient {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.65rem;
    padding: 0.45rem 0.55rem;
    margin-bottom: 0.35rem;
    border-radius: 10px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: #f8fafc;
}

.lux-feedback-recipient:last-child {
    margin-bottom: 0;
}

.lux-feedback-recipient__main {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    min-width: 0;
    flex: 1;
}

.lux-feedback-recipient__icon {
    font-size: 0.9rem;
    flex-shrink: 0;
}

.lux-feedback-recipient__name {
    font-size: 0.8125rem;
    font-weight: 700;
    color: #0f172a;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.lux-feedback-recipient__email {
    font-size: 0.6875rem;
    color: #64748b;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.lux-feedback-recipient__actions {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    flex-shrink: 0;
}

.lux-feedback-recipient__date {
    font-size: 0.6875rem;
    color: #94a3b8;
    white-space: nowrap;
}

.lux-feedback-status-pill {
    display: inline-flex;
    align-items: center;
    padding: 0.15rem 0.45rem;
    border-radius: 999px;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
}

.lux-feedback-status-pill.is-draft {
    background: rgba(59, 130, 246, 0.12);
    color: #1d4ed8;
}

.lux-feedback-status-pill.is-requested {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-feedback-status-pill.is-received {
    background: rgba(245, 158, 11, 0.15);
    color: #b45309;
}

.lux-feedback-status-pill.is-reviewed {
    background: rgba(22, 163, 74, 0.12);
    color: #15803d;
}

.lux-feedback-status-pill.is-closed {
    background: rgba(15, 23, 42, 0.08);
    color: #334155;
}

/* Template config panel */
.right_sidebar.lux-create-panel--feedback-template {
    width: min(1120px, 96vw) !important;
    right: calc(-1 * min(1120px, 96vw) - 24px) !important;
}

.right_sidebar.lux-create-panel--feedback-template.open {
    right: 0 !important;
}

.right_sidebar.lux-create-panel--feedback-template .lux-create-panel__body {
    display: flex;
    flex-direction: column;
    min-height: 0;
    overflow: hidden;
    padding: 0;
}

.lux-feedback-template-panel__body {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

/* Feedback request create panel */
.right_sidebar.lux-create-panel--feedback-request {
    width: min(1080px, 96vw) !important;
    right: calc(-1 * min(1080px, 96vw) - 24px) !important;
}

.right_sidebar.lux-create-panel--feedback-request.open {
    right: 0 !important;
}

.right_sidebar.lux-create-panel--feedback-request .lux-create-panel__body {
    display: flex;
    flex-direction: column;
    min-height: 0;
    overflow: hidden;
    padding: 0;
}

.lux-feedback-request-panel__body {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.lux-create-panel--feedback-request .lux-fb-create-form--panel {
    flex: 1;
    min-height: 0;
    height: 100%;
}

.lux-create-panel--feedback-request .lux-fb-create-form__scroll {
    flex: 1;
    min-height: 0;
    overflow: auto;
}

.lux-create-panel--feedback-request .lux-fb-create-form__aside {
    position: static;
    top: auto;
}

.lux-create-panel--feedback-request .lux-fb-create-section--schedule {
    overflow: visible;
}

.lux-create-panel--feedback-request .custom-select__menu-portal,
.lux-create-panel--feedback-request .lux-date-picker-popper,
body:has(#lux-feedback-request-create.open) #lux-date-picker-portal .react-datepicker-popper {
    z-index: 10150 !important;
}

.lux-create-panel--feedback-request .react-datepicker-wrapper {
    display: block;
    width: 100%;
}

.lux-create-panel--feedback-request .react-datepicker-wrapper .form-control {
    width: 100%;
}

/* Feedback template editor */
.lux-feedback-template-editor {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-height: 0;
    height: 100%;
}

.lux-feedback-template-editor__layout {
    display: grid;
    grid-template-columns: minmax(15rem, 18rem) minmax(0, 1fr);
    flex: 1;
    min-height: 0;
    margin: 0.75rem 0.85rem 0;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 16px;
    overflow: hidden;
    background: #fff;
    box-shadow: 0 12px 32px rgba(15, 23, 42, 0.06);
}

.lux-feedback-template-editor__list-pane {
    display: flex;
    flex-direction: column;
    min-height: 0;
    border-right: 1px solid #e2e8f0;
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06), transparent 55%),
        #f8fafc;
}

.lux-feedback-template-editor__list-head {
    padding: 0.85rem 0.75rem 0.7rem;
    border-bottom: 1px solid #e2e8f0;
}

.lux-feedback-template-editor__list-title-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
}

.lux-feedback-template-editor__list-label {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-feedback-template-editor__count {
    padding: 0.1rem 0.45rem;
    border-radius: 999px;
    font-size: 0.625rem;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    border: 1px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18);
}

.lux-feedback-template-editor__filter {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin-top: 0.55rem;
    padding: 0.42rem 0.55rem;
    border: 1px solid #e2e8f0;
    border-radius: 12px;
    background: #fff;
    color: #94a3b8;
}

.lux-feedback-template-editor__filter input {
    flex: 1;
    min-width: 0;
    border: none;
    outline: none;
    background: transparent;
    font-size: 0.75rem;
    font-weight: 600;
    color: #0f172a;
}

.lux-feedback-template-editor__new {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.35rem;
    width: 100%;
    margin-top: 0.55rem;
    padding: 0.45rem 0.65rem;
    border: 1px dashed rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05);
    font-size: 0.6875rem;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
    cursor: pointer;
    transition: border-color 0.14s ease, background 0.14s ease;
}

.lux-feedback-template-editor__new:hover,
.lux-feedback-template-editor__new.is-inline:hover {
    border-style: solid;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-feedback-template-editor__new.is-inline {
    width: auto;
    margin-top: 0.65rem;
}

.lux-feedback-template-editor__list-body {
    flex: 1;
    min-height: 0;
    overflow: auto;
    padding: 0.45rem 0.55rem 0.65rem;
}

.lux-feedback-template-editor__list {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    margin: 0;
    padding: 0;
    list-style: none;
}

.lux-feedback-template-editor__list-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 0.35rem;
    padding: 1.25rem 0.75rem;
    color: #64748b;
    font-size: 0.75rem;
}

.lux-feedback-template-editor__list-empty i {
    font-size: 1.35rem;
    color: #94a3b8;
}

.lux-feedback-template-editor__list-empty strong {
    color: #0f172a;
    font-size: 0.8125rem;
}

.lux-feedback-template-editor__item {
    border: 1px solid #e2e8f0;
    border-radius: 12px;
    background: #fff;
    transition: border-color 0.14s ease, box-shadow 0.14s ease;
}

.lux-feedback-template-editor__item.is-selected {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.38);
    box-shadow: 0 8px 20px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-feedback-template-editor__item-main {
    display: flex;
    align-items: flex-start;
    gap: 0.3rem;
    padding: 0.42rem 0.45rem;
}

.lux-feedback-template-editor__item-select {
    flex: 1;
    min-width: 0;
    padding: 0;
    border: none;
    background: transparent;
    text-align: left;
    cursor: pointer;
}

.lux-feedback-template-editor__item-name {
    display: block;
    font-size: 0.75rem;
    font-weight: 800;
    color: #0f172a;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-feedback-template-editor__item-meta {
    display: block;
    margin-top: 0.12rem;
    font-size: 0.625rem;
    font-weight: 600;
    color: #94a3b8;
}

.lux-feedback-template-editor__item-actions {
    display: inline-flex;
    align-items: center;
    gap: 0.15rem;
    flex-shrink: 0;
}

.lux-feedback-template-editor__item-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.65rem;
    height: 1.65rem;
    border: 1px solid #e2e8f0;
    border-radius: 9px;
    background: #fff;
    color: #64748b;
    text-decoration: none;
    cursor: pointer;
    transition: border-color 0.14s ease, color 0.14s ease, background 0.14s ease;
}

.lux-feedback-template-editor__item-action:hover {
    color: var(--lux-primary-dark, #3730a3);
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

.lux-feedback-template-editor__item-action.is-danger:hover {
    color: #be123c;
    border-color: rgba(244, 63, 94, 0.35);
    background: #fff1f2;
}

.lux-feedback-template-editor__form-pane {
    min-width: 0;
    min-height: 0;
    overflow: auto;
    padding: 0.85rem 0.95rem 0.75rem;
    background: #fff;
}

.lux-feedback-template-editor__status {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    margin-bottom: 0.75rem;
    padding: 0.65rem 0.75rem;
    border-radius: 14px;
    border: 1px solid #e2e8f0;
    background:
        radial-gradient(circle at 100% 0%, rgba(20, 184, 166, 0.08), transparent 50%),
        #f8fafc;
}

.lux-feedback-template-editor__status-icon {
    width: 2rem;
    height: 2rem;
    display: grid;
    place-items: center;
    border-radius: 11px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    color: var(--lux-primary, #5b5ff4);
    flex-shrink: 0;
}

.lux-feedback-template-editor__status-copy {
    flex: 1;
    min-width: 0;
}

.lux-feedback-template-editor__status-copy strong {
    display: block;
    font-size: 0.8125rem;
    color: #0f172a;
}

.lux-feedback-template-editor__status-copy p {
    margin: 0.15rem 0 0;
    font-size: 0.6875rem;
    color: #64748b;
}

.lux-feedback-template-editor__preview-link {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    padding: 0.3rem 0.55rem;
    border-radius: 999px;
    border: 1px solid #e2e8f0;
    background: #fff;
    font-size: 0.625rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--lux-primary-dark, #3730a3);
    text-decoration: none;
}

.lux-feedback-template-editor__preview-link:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

/* Feedback template — editor hero (create / edit / preview) */
.lux-ft-hero {
    position: relative;
    margin-bottom: 0.75rem;
    padding: 0.85rem 0.95rem;
    border-radius: 16px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.9));
    box-shadow: 0 10px 28px rgba(15, 23, 42, 0.06);
    overflow: hidden;
}

.lux-ft-hero__glow {
    position: absolute;
    top: -45%;
    right: -8%;
    width: 220px;
    height: 220px;
    border-radius: 50%;
    pointer-events: none;
    background: radial-gradient(circle, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16), transparent 68%);
}

.lux-ft-hero--create .lux-ft-hero__glow {
    background: radial-gradient(circle, rgba(20, 184, 166, 0.2), transparent 68%);
}

.lux-ft-hero--preview .lux-ft-hero__glow {
    background: radial-gradient(circle, rgba(148, 163, 184, 0.18), transparent 68%);
}

.lux-ft-hero__inner {
    position: relative;
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.75rem;
    flex-wrap: wrap;
}

.lux-ft-hero__main {
    flex: 1;
    min-width: 0;
}

.lux-ft-hero__badges {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.35rem;
    margin-bottom: 0.35rem;
}

.lux-ft-hero__mode-pill {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    padding: 0.22rem 0.55rem;
    border-radius: 999px;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
}

.lux-ft-hero__mode-pill.is-create {
    color: #0f766e;
    background: #ccfbf1;
    border: 1px solid #99f6e4;
}

.lux-ft-hero__mode-pill.is-edit {
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    border: 1px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.2);
}

.lux-ft-hero__mode-pill.is-preview {
    color: #475569;
    background: #f1f5f9;
    border: 1px solid #e2e8f0;
}

.lux-ft-hero__mode-pill.is-idle {
    color: #64748b;
    background: #f8fafc;
    border: 1px solid #e2e8f0;
}

.lux-ft-hero__ref {
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    color: #94a3b8;
}

.lux-ft-hero__title {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 800;
    letter-spacing: -0.02em;
    color: #0f172a;
    line-height: 1.25;
}

.lux-ft-hero__subtitle {
    margin: 0.3rem 0 0;
    max-width: 34rem;
    font-size: 0.6875rem;
    line-height: 1.45;
    color: #64748b;
}

.lux-ft-hero__chips {
    display: flex;
    flex-wrap: wrap;
    gap: 0.3rem;
    margin: 0.5rem 0 0;
    padding: 0;
    list-style: none;
}

.lux-ft-hero__chip {
    display: inline-flex;
    align-items: center;
    gap: 0.22rem;
    padding: 0.18rem 0.45rem;
    border-radius: 999px;
    font-size: 0.625rem;
    font-weight: 700;
    color: #475569;
    background: #fff;
    border: 1px solid #e2e8f0;
}

.lux-ft-hero__chip.is-muted {
    color: #64748b;
    background: #f8fafc;
}

.lux-ft-hero__aside {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.35rem;
    flex-shrink: 0;
}

.lux-ft-hero__action {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.38rem 0.65rem;
    border-radius: 12px;
    font-size: 0.6875rem;
    font-weight: 800;
    cursor: pointer;
    text-decoration: none;
    border: 1px solid #e2e8f0;
    background: #fff;
    color: var(--lux-primary-dark, #3730a3);
}

.lux-ft-hero__action--preview:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

.lux-ft-hero__action--ghost {
    color: #64748b;
    background: #f8fafc;
}

.lux-ft-hero__action--ghost:hover {
    color: #0f172a;
    border-color: #cbd5e1;
}

/* Feedback template — details panel */
.lux-ft-details {
    margin-bottom: 0.7rem;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 16px;
    background: #fff;
    box-shadow: 0 6px 20px rgba(15, 23, 42, 0.04);
    overflow: hidden;
}

.lux-ft-details--empty {
    background: rgba(248, 250, 252, 0.85);
}

.lux-ft-details__empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 0.3rem;
    padding: 1.25rem 1rem;
    color: #64748b;
}

.lux-ft-details__empty i {
    font-size: 1.25rem;
    color: #94a3b8;
}

.lux-ft-details__empty strong {
    font-size: 0.8125rem;
    color: #334155;
}

.lux-ft-details__empty p {
    margin: 0;
    max-width: 18rem;
    font-size: 0.6875rem;
    line-height: 1.45;
}

.lux-ft-details__head {
    display: flex;
    align-items: flex-start;
    gap: 0.6rem;
    padding: 0.7rem 0.85rem;
    border-bottom: 1px solid #e2e8f0;
    background: linear-gradient(180deg, rgba(248, 250, 252, 0.95), rgba(255, 255, 255, 0.6));
}

.lux-ft-details__head-icon {
    width: 2.1rem;
    height: 2.1rem;
    display: grid;
    place-items: center;
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary, #5b5ff4);
    flex-shrink: 0;
}

.lux-ft-details__head-copy h3 {
    margin: 0;
    font-size: 0.875rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-ft-details__head-copy p {
    margin: 0.12rem 0 0;
    font-size: 0.6875rem;
    color: #64748b;
    line-height: 1.4;
}

.lux-ft-details__body {
    padding: 0.75rem 0.85rem 0.85rem;
}

.lux-ft-details__grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.55rem 0.65rem;
}

.lux-ft-field {
    padding: 0.55rem 0.6rem;
    border: 1px solid #e2e8f0;
    border-radius: 14px;
    background: rgba(248, 250, 252, 0.55);
}

.lux-ft-field--full {
    grid-column: 1 / -1;
}

.lux-ft-field__head {
    display: flex;
    align-items: flex-start;
    gap: 0.45rem;
    margin-bottom: 0.4rem;
}

.lux-ft-field__icon {
    width: 1.65rem;
    height: 1.65rem;
    display: grid;
    place-items: center;
    border-radius: 10px;
    background: #fff;
    border: 1px solid #e2e8f0;
    color: var(--lux-primary, #5b5ff4);
    font-size: 0.8rem;
    flex-shrink: 0;
}

.lux-ft-field__title {
    display: block;
    font-size: 0.6875rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-ft-field__hint {
    display: block;
    margin-top: 0.08rem;
    font-size: 0.625rem;
    color: #94a3b8;
    line-height: 1.35;
}

.lux-ft-field__control .form-group {
    margin-bottom: 0 !important;
}

.lux-ft-field__control .form-control,
.lux-ft-field__control textarea.form-control {
    border-radius: 12px !important;
    border: 1px solid #e2e8f0 !important;
    font-size: 0.8125rem !important;
    font-weight: 600 !important;
    background: #fff !important;
}

.lux-ft-field__control .custom-select__control {
    min-height: 36px;
    border-radius: 12px;
    border-color: #e2e8f0;
    font-size: 0.75rem;
    font-weight: 600;
    background: #fff;
}

.lux-ft-details__access {
    margin-top: 0.65rem;
    padding-top: 0.65rem;
    border-top: 1px dashed #e2e8f0;
}

.lux-ft-details__access-head {
    display: flex;
    align-items: flex-start;
    gap: 0.5rem;
    margin-bottom: 0.5rem;
}

.lux-ft-details__access-icon {
    width: 1.85rem;
    height: 1.85rem;
    display: grid;
    place-items: center;
    border-radius: 11px;
    background: rgba(20, 184, 166, 0.1);
    color: #0d9488;
    flex-shrink: 0;
}

.lux-ft-details__access-head h4 {
    margin: 0;
    font-size: 0.75rem;
