}

.lux-feedback-popover__section + .lux-feedback-popover__section {
    margin-top: 1rem;
}

.lux-feedback-popover__section-title {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin: 0 0 0.55rem;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-feedback-popover__section-count {
    margin-left: auto;
    padding: 0.1rem 0.45rem;
