}

.lux-feedback-popover__detail-value {
    display: block;
    font-size: 0.75rem;
    font-weight: 600;
    color: #0f172a;
    line-height: 1.45;
}

.lux-feedback-popover__detail-value a {
    color: var(--lux-primary, #5b5ff4);
}

.lux-feedback-popover__recipients {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.lux-feedback-popover__foot {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: 0.45rem;
    padding: 0.65rem 1.1rem;
    border-top: 1px solid rgba(148, 163, 184, 0.22);
    background: rgba(248, 250, 252, 0.95);
}

@media (max-width: 720px) {
    .lux-feedback-popover__kpis {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .lux-feedback-popover__detail-grid {
        grid-template-columns: 1fr;
    }

    .lux-feedback-card__open-hint span {
        display: none;
    }
}
/* ========== Public feedback request form (client + template preview) ========== */

body.lux-fb-body {
    overflow-y: auto !important;
}

.lux-fb-bool-options {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem 0.75rem;
}

.lux-fb-page {
    --lux-fb-font: "Plus Jakarta Sans", "Inter", system-ui, sans-serif;
    min-height: 100vh;
    padding: 0 0 3rem;
    font-family: var(--lux-fb-font);
    color: #0f172a;
    background:
        radial-gradient(ellipse 120% 80% at 0% -20%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14), transparent 55%),
        radial-gradient(ellipse 90% 60% at 100% 0%, rgba(14, 165, 233, 0.1), transparent 50%),
        linear-gradient(180deg, #f8fafc 0%, #eef2ff 42%, #f1f5f9 100%);
}

.lux-fb-page__inner {
    width: min(1060px, calc(100% - 2rem));
    margin: 0 auto;
}

.lux-fb-page__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding: 1.15rem 0 0.85rem;
}

.lux-fb-page__logo {
    height: 2.75rem;
    width: auto;
    max-width: 200px;
    object-fit: contain;
}

.lux-fb-page__logo-mark {
    height: 2.75rem;
    width: auto;
    opacity: 0.18;
}

.lux-fb-page__shell {
    position: relative;
    border-radius: 24px;
    border: 1px solid rgba(255, 255, 255, 0.85);
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.98) 0%, rgba(248, 250, 252, 0.96) 100%);
    box-shadow:
        0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06),
        0 28px 64px rgba(15, 23, 42, 0.1);
    overflow: hidden;
}

.lux-fb-page__ribbon {
    position: absolute;
    top: 1rem;
    right: -2.75rem;
    z-index: 20;
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.35rem 3rem;
    transform: rotate(32deg);
    background: linear-gradient(135deg, #f59e0b, #d97706);
    box-shadow: 0 8px 20px rgba(217, 119, 6, 0.35);
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: #fff;
    pointer-events: none;
}

.lux-fb-page__ribbon i {
    font-size: 0.75rem;
}

/* Main + sidebar — form left, guide panel right */
.lux-fb-shell-layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 280px;
    align-items: stretch;
}

.lux-fb-shell-main {
    min-width: 0;
}

.lux-fb-hero {
    padding: 1.5rem 1.75rem 1.15rem;
    border-bottom: 1px solid rgba(148, 163, 184, 0.2);
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1), transparent 48%),
        linear-gradient(135deg, rgba(255, 255, 255, 0.95), rgba(241, 245, 249, 0.9));
    text-align: left;
}

.lux-fb-shell-main > .lux-fb-alert {
    margin: 0.75rem 1.75rem 0;
}

/* Rich aside — fixed-width right column */
.lux-fb-rich {
    box-sizing: border-box;
    width: 280px;
    max-width: 280px;
    padding: 1.15rem 1rem 1.25rem;
    border-left: 1px solid rgba(148, 163, 184, 0.2);
    background:
        linear-gradient(180deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06), rgba(255, 255, 255, 0.98));
    position: sticky;
    top: 0;
    align-self: start;
    max-height: 100vh;
    overflow-x: hidden;
    overflow-y: auto;
}

.lux-fb-rich__badge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    margin-bottom: 0.5rem;
    padding: 0.25rem 0.6rem;
    border-radius: 999px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: var(--lux-primary-dark, #3730a3);
}

.lux-fb-rich__lead {
    margin: 0 0 1rem;
    font-size: 0.8125rem;
    line-height: 1.55;
    color: #475569;
}

.lux-fb-rich__steps {
    list-style: none;
    margin: 0 0 1rem;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.lux-fb-rich__step {
    display: flex;
    align-items: flex-start;
    gap: 0.55rem;
}

.lux-fb-rich__step-num {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.5rem;
    height: 1.5rem;
    border-radius: 999px;
    background: var(--lux-primary, #5b5ff4);
    font-size: 0.6875rem;
    font-weight: 800;
    color: #fff;
    flex-shrink: 0;
}

.lux-fb-rich__step strong {
    display: block;
    font-size: 0.75rem;
    color: #0f172a;
}

.lux-fb-rich__step span {
    display: block;
    font-size: 0.6875rem;
    color: #94a3b8;
}

.lux-fb-rich__legend {
    margin-bottom: 1rem;
    padding: 0.65rem 0.7rem;
    border-radius: 12px;
    border: 1px solid rgba(148, 163, 184, 0.28);
    background: rgba(255, 255, 255, 0.85);
}

.lux-fb-rich__legend-title {
    margin: 0 0 0.45rem;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-fb-rating-legend {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.28rem;
}

.lux-fb-rating-legend li {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    font-size: 0.6875rem;
    color: #64748b;
}

.lux-fb-rating-legend__stars {
    display: inline-flex;
    gap: 0.05rem;
    min-width: 4.5rem;
}

.lux-fb-rating-legend__stars .fa-star {
    font-size: 0.55rem;
    color: #cbd5e1;
}

.lux-fb-rating-legend li.is-excellent .fa-star,
.lux-fb-rating-legend li.is-great .fa-star { color: #16a34a; }
.lux-fb-rating-legend li.is-good .fa-star { color: #3b82f6; }
.lux-fb-rating-legend li.is-fair .fa-star { color: #f97316; }
.lux-fb-rating-legend li.is-poor .fa-star { color: #ef4444; }

.lux-fb-rich__pillars {
    display: flex;
    flex-direction: column;
    gap: 0.55rem;
    margin-bottom: 1rem;
}

.lux-fb-rich__pillar {
    display: flex;
    gap: 0.5rem;
    padding: 0.55rem 0.6rem;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.88);
    border: 1px solid rgba(148, 163, 184, 0.22);
}

.lux-fb-rich__pillar i {
    color: var(--lux-primary, #5b5ff4);
    margin-top: 0.1rem;
}

.lux-fb-rich__pillar strong {
    display: block;
    font-size: 0.75rem;
    color: #0f172a;
}

.lux-fb-rich__pillar p {
    margin: 0.15rem 0 0;
    font-size: 0.6875rem;
    line-height: 1.45;
    color: #64748b;
}

.lux-fb-rich__quote {
    margin: 0;
    padding: 0.55rem 0.65rem;
    border-left: 3px solid var(--lux-primary, #5b5ff4);
    border-radius: 0 10px 10px 0;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05);
}

/* Reset legacy bootstrap rows inside the form */
.lux-fb-page .row {
    margin-left: 0;
    margin-right: 0;
}

.lux-fb-page [class*="col-"] {
    position: relative;
    width: 100%;
    max-width: 100%;
    padding-left: 0;
    padding-right: 0;
    flex: none;
}

.lux-fb-rich__quote p {
    margin: 0;
    font-size: 0.75rem;
    font-style: italic;
    line-height: 1.5;
    color: #475569;
}

.lux-fb-rich__quote footer {
