}

.lux-fb-hero__meta {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
}

.lux-fb-hero__chip {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.35rem 0.7rem;
    border-radius: 999px;
    border: 1px solid rgba(148, 163, 184, 0.35);
    background: rgba(255, 255, 255, 0.92);
