    font-weight: 700;
    color: #334155;
}

.lux-fb-hero__chip strong {
    color: #0f172a;
    font-weight: 800;
}

.lux-fb-progress {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin-top: 1rem;
    padding: 0.55rem 0.75rem;
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
    border: 1px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-fb-progress__bar {
    flex: 1;
    height: 6px;
    border-radius: 999px;
    background: rgba(148, 163, 184, 0.25);
    overflow: hidden;
}

.lux-fb-progress__fill {
    height: 100%;
    border-radius: inherit;
    background: linear-gradient(90deg, var(--lux-primary, #5b5ff4), #0ea5e9);
    transition: width 0.25s ease;
}

.lux-fb-progress__text {
    font-size: 0.6875rem;
    font-weight: 700;
    color: #64748b;
    white-space: nowrap;
}

.lux-fb-form {
    padding: 1.25rem 1.75rem 1.75rem;
}

.lux-fb-section {
    margin-bottom: 1.5rem;
}

.lux-fb-section__head {
    margin: 0 0 0.85rem;
    padding-bottom: 0.55rem;
    border-bottom: 1px dashed rgba(148, 163, 184, 0.4);
}

.lux-fb-section__title {
    margin: 0;
    font-size: 0.8125rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-fb-section__hint {
    margin: 0.25rem 0 0;
