.lux-fb-q__required {
    margin-left: 0.15rem;
    color: #dc2626;
    font-weight: 800;
}

.lux-fb-q__hint {
    display: block;
    margin-top: 0.35rem;
    font-size: 0.75rem;
    color: #94a3b8;
